		if ruleMap, ok := ruleRaw.(map[string]interface{}); ok {
			for ruleName, ruleVal := range ruleMap {
				// ruleVal is map
				if rm, ok := ruleVal.(map[string]interface{}); ok {
					rc := RuleConfig{}
					// Check Disabled
					if v, ok := rm["Disabled"]; ok {
						if b, ok := v.(bool); ok {
							rc.Disabled = b
						}
					}
					if v, ok := rm["disabled"]; ok {
						if b, ok := v.(bool); ok {
							rc.Disabled = b
						}
					}
					if v, ok := rm["Severity"]; ok {
						if s, ok := v.(string); ok {
							rc.Severity = s
						}
					}
					if v, ok := rm["severity"]; ok {
						if s, ok := v.(string); ok {
							rc.Severity = s
						}
					}
					if v, ok := rm["Confidence"]; ok {
						switch val := v.(type) {
						case float64:
							rc.Confidence = &val
						case int64:
							f := float64(val)
							rc.Confidence = &f
						}
					}
					if v, ok := rm["confidence"]; ok {
						switch val := v.(type) {
						case float64:
							rc.Confidence = &val
						case int64:
							f := float64(val)
							rc.Confidence = &f
						}
					}
					if v, ok := rm["Exclude"]; ok {
						if arr, ok := v.([]interface{}); ok {
							for _, item := range arr {
								if s, ok := item.(string); ok {
									rc.Exclude = append(rc.Exclude, s)
								}
							}
						}
					}
					if v, ok := rm["exclude"]; ok {
						if arr, ok := v.([]interface{}); ok {
							for _, item := range arr {
								if s, ok := item.(string); ok {
									rc.Exclude = append(rc.Exclude, s)
								}
							}
						}
					}
					if v, ok := rm["Arguments"]; ok {
						if arr, ok := v.([]interface{}); ok {
							rc.Arguments = arr
						}
					}
					if v, ok := rm["arguments"]; ok {
						if arr, ok := v.([]interface{}); ok {
							rc.Arguments = arr
						}
					}
					// Merge with existing if present
					if existing, exists := cfg.Rule[ruleName]; exists {
						// Merge logic: override with manual parsed if not zero
						if rc.Disabled {
							existing.Disabled = rc.Disabled
						}
						// Actually if existing already has Disabled false but manual true, we want true
						// So we will just take rc if it has values
						// For simplicity, if rule already exists from toml unmarshal, keep it but overwrite disabled if manual says true
						// Let's just use manual if it has any fields
						if rc.Severity != "" {
							existing.Severity = rc.Severity
						}
						if rc.Confidence != nil {
							existing.Confidence = rc.Confidence
						}
						if len(rc.Exclude) > 0 {
							existing.Exclude = rc.Exclude
						}
						if len(rc.Arguments) > 0 {
							existing.Arguments = rc.Arguments
						}
						if rc.Disabled {
							existing.Disabled = true
						}
						cfg.Rule[ruleName] = existing
					} else {
						cfg.Rule[ruleName] = rc
					}
				}
			}
		}
	}

	// Validate rules exist
	if err := validateRules(cfg.Rule); err != nil {
		return nil, err
	}

	// If config file was explicitly provided and contains no rules and no top-level settings, should we still treat as empty? That's fine.

	return cfg, nil
}

