// File collection
func collectFiles(patterns []string, globalExclude []string, flagExcludes []string) ([]string, error) {
	// Merge excludes
	excludes := append([]string{}, globalExclude...)
	excludes = append(excludes, flagExcludes...)

	// For each pattern, resolve Go files
	// Patterns can be ./..., ., package path, or file paths like main.go, or directory globs like foo/...
	// Simplified: use filepath.Glob and also handle ./... via walking.

	var files []string
	for _, pat := range patterns {
		// If pat contains "...", treat as recursive
		if strings.Contains(pat, "...") {
			// Remove ... and get base dir
			base := strings.TrimSuffix(pat, "/...")
			base = strings.TrimSuffix(base, "...")
			if base == "" || base == "." || base == "./" {
				base = "."
			}
			// Walk base recursively
			err := filepath.Walk(base, func(path string, info os.FileInfo, err error) error {
				if err != nil {
					return nil
				}
				if info.IsDir() {
					// Check if dir matches exclude pattern?
					// If exclude pattern is like "sub/..." then skip that dir
					for _, ex := range excludes {
						if matchExclude(ex, path) {
							return filepath.SkipDir
						}
					}
					return nil
				}
				if !strings.HasSuffix(path, ".go") {
					return nil
				}
				// Check exclude
				for _, ex := range excludes {
					if matchExclude(ex, path) {
						return nil
					}
				}
				files = append(files, path)
				return nil
			})
			if err != nil {
				return nil, err
			}
		} else {
			// If pat is a file
			if strings.HasSuffix(pat, ".go") {
				// Check if file exists
				if _, err := os.Stat(pat); err == nil {
					// Check exclude
					excluded := false
					for _, ex := range excludes {
						if matchExclude(ex, pat) {
							excluded = true
							break
						}
					}
					if !excluded {
						files = append(files, pat)
					}
				} else {
					// Try as package pattern without ...?
					// If pat is directory, collect its Go files non-recursive
					if info, err := os.Stat(pat); err == nil && info.IsDir() {
						entries, err := os.ReadDir(pat)
						if err == nil {
							for _, e := range entries {
								if !e.IsDir() && strings.HasSuffix(e.Name(), ".go") {
									full := filepath.Join(pat, e.Name())
									excluded := false
									for _, ex := range excludes {
										if matchExclude(ex, full) {
											excluded = true
											break
										}
									}
									if !excluded {
										files = append(files, full)
									}
								}
							}
						}
					}
				}
			} else {
				// Directory or package
				// Trim ./ prefix
				cleanPat := pat
				if strings.HasPrefix(cleanPat, "./") {
					cleanPat = cleanPat[2:]
				}
				if cleanPat == "." || cleanPat == "" {
					cleanPat = "."
				}
				// If it's a directory, collect non-recursive go files
				if info, err := os.Stat(cleanPat); err == nil && info.IsDir() {
					entries, err := os.ReadDir(cleanPat)
					if err == nil {
						for _, e := range entries {
							if !e.IsDir() && strings.HasSuffix(e.Name(), ".go") {
								full := filepath.Join(cleanPat, e.Name())
								excluded := false
								for _, ex := range excludes {
									if matchExclude(ex, full) {
										excluded = true
										break
									}
								}
								if !excluded {
									files = append(files, full)
								}
							}
						}
					}
				} else {
					// Try glob
					matches, err := filepath.Glob(pat)
					if err == nil {
						for _, m := range matches {
							if strings.HasSuffix(m, ".go") {
								info, err := os.Stat(m)
								if err == nil && !info.IsDir() {
									excluded := false
									for _, ex := range excludes {
										if matchExclude(ex, m) {
											excluded = true
											break
										}
									}
									if !excluded {
										files = append(files, m)
									}
								}
							} else {
								// If match is dir, collect its files non-recursive
								if info, err := os.Stat(m); err == nil && info.IsDir() {
									entries, _ := os.ReadDir(m)
									for _, e := range entries {
										if !e.IsDir() && strings.HasSuffix(e.Name(), ".go") {
											full := filepath.Join(m, e.Name())
											excluded := false
											for _, ex := range excludes {
												if matchExclude(ex, full) {
													excluded = true
													break
												}
											}
											if !excluded {
												files = append(files, full)
											}
										}
									}
								}
							}
						}
					}
				}
			}
		}
	}

	// Deduplicate
	seen := make(map[string]bool)
	var uniq []string
	for _, f := range files {
		if !seen[f] {
			seen[f] = true
			uniq = append(uniq, f)
		}
	}
	return uniq, nil
}

func matchExclude(pattern, path string) bool {
	// pattern can be like "foo/...", "foo/bar.go", "sub/...", "a.go"
	// If pattern ends with "/...", then check if path has prefix of pattern without "/..."
	if strings.HasSuffix(pattern, "/...") {
		base := strings.TrimSuffix(pattern, "/...")
		// Check if path == base or path starts with base + "/"
		if path == base || strings.HasPrefix(path, base+"/") {
			return true
		}
		// Also handle pattern like "pkg/foo/..." relative?
		// Try cleaning
		return strings.HasPrefix(path, base)
	}
	// If pattern contains "..." anywhere else, treat as prefix
	if strings.Contains(pattern, "...") {
		base := strings.Split(pattern, "...")[0]
		return strings.HasPrefix(path, base)
	}
	// Otherwise, use filepath.Match for glob
	// Also try simple equality
	if pattern == path {
		return true
	}
	// Try glob match
	matched, err := filepath.Match(pattern, path)
	if err == nil && matched {
		return true
	}
	// Also try matching base name?
	if matched, _ := filepath.Match(pattern, filepath.Base(path)); matched {
		return true
	}
	// Try if pattern is directory and path is inside?
	// If pattern without glob matches directory prefix
	if strings.HasPrefix(path, pattern+"/") {
		return true
	}
	return false
}

func filterByConfidence(failures []Failure, threshold float64) []Failure {
	if threshold == 0 {
		return failures
	}
	var out []Failure
	for _, f := range failures {
		if f.Confidence >= threshold {
			out = append(out, f)
		}
	}
	return out
}

func filterByRuleExclude(failures []Failure, cfg *Config) []Failure {
	var out []Failure
	for _, f := range failures {
		// Check rule-specific exclude
		if rc, ok := cfg.Rule[f.RuleName]; ok {
			excluded := false
			for _, ex := range rc.Exclude {
				if matchExclude(ex, f.Position.Start.Filename) {
					excluded = true
					break
				}
			}
			if excluded {
				continue
			}
		}
		out = append(out, f)
	}
	return out
}

func lintFiles(files []string, cfg *Config, enabledRules map[string]RuleConfig) ([]Failure, error) {
	var allFailures []Failure
	for _, filePath := range files {
		// Check ignoreGeneratedHeader
		if cfg.IgnoreGeneratedHeader {
			// Read first few lines to check for "Code generated" or "DO NOT EDIT"
			content, err := os.ReadFile(filePath)
			if err == nil {
				// Look for generated header in first 5 lines
				lines := strings.Split(string(content), "\n")
				for i := 0; i < len(lines) && i < 5; i++ {
					if strings.Contains(lines[i], "Code generated") && strings.Contains(lines[i], "DO NOT EDIT") {
						// Skip file
						goto nextFile
					}
					if strings.Contains(lines[i], "DO NOT EDIT") {
						// Also skip?
						goto nextFile
					}
				}
			}
		}

		failures, err := lintFile(filePath, cfg, enabledRules)
		if err != nil {
			// If file has syntax error, original reports something like "invalid file main.go: ..."
			// Let's produce a failure with empty RuleName and Category validity
			// But actually we should still continue
			// For simplicity, if parse error, create a failure similar to original:
			allFailures = append(allFailures, Failure{
				Severity:       "warning",
				FailureMessage:  fmt.Sprintf("invalid file %s: %s", filePath, err.Error()),
				RuleName:       "",
				Category:       "validity",
				Confidence:     1,
				Position: Position{
					Start: Pos{Filename: filePath, Line: 1, Column: 1, Offset: 0},
					End:   Pos{Filename: "", Line: 0, Column: 0, Offset: 0},
				},
			})
			continue
		}
		allFailures = append(allFailures, failures...)
	nextFile:
	}

	return allFailures, nil
}

func lintFile(filePath string, cfg *Config, enabledRules map[string]RuleConfig) ([]Failure, error) {
	fset := token.NewFileSet()
	src, err := os.ReadFile(filePath)
	if err != nil {
		return nil, err
	}
	// Parse file
	file, err := parser.ParseFile(fset, filePath, src, parser.ParseComments)
	if err != nil {
		// Return error for invalid file handling
		return nil, err
	}

	// Build list of comment directives
	// We need to handle //revive:disable, //revive:enable, //revive:disable-next-line, //revive:disable-line, etc.

	// We'll create a structure to track disabled rules per line
	type directive struct {
		line int
		// disabled rules: empty means all disabled
		disableAll bool
		disableRules map[string]bool
		enableAll bool
		enableRules map[string]bool
		nextLineDisable bool
		nextLineRules map[string]bool
		lineDisable bool
		lineRules map[string]bool
	}

	// For simplicity, we'll implement a more straightforward approach:
	// Track global disabled state, and per-line disables.

	// Map line -> set of disabled rules for that line
	disabledRulesPerLine := make(map[int]map[string]bool) // if map contains true, rule disabled for that line; if map empty but disabledAll true, then all disabled
	disabledAllPerLine := make(map[int]bool)

	// Global state
	globalDisabledAll := false
	globalDisabled := make(map[string]bool)

	// For disable-next-line handling, we need to know lines
	// Iterate over file.Comments
	for _, cg := range file.Comments {
		for _, c := range cg.List {
			text := c.Text
			// Get position
			pos := fset.Position(c.Pos())
			line := pos.Line

			// Check if comment contains revive directive
			// Format: //revive:disable, //revive:enable, //revive:disable-next-line, //revive:disable-line, etc.
			if !strings.Contains(text, "revive:") {
				continue
			}
			// Extract directive part
			// Remove /* */ or // prefix
			// For // comments: text starts with //, then maybe //revive:disable etc.
			// For /* */ comments: might be similar
			// We'll strip leading // or /* and trailing */
			trimmed := strings.TrimSpace(text)
			if strings.HasPrefix(trimmed, "//") {
				trimmed = strings.TrimPrefix(trimmed, "//")
				trimmed = strings.TrimSpace(trimmed)
			} else if strings.HasPrefix(trimmed, "/*") {
				trimmed = strings.TrimPrefix(trimmed, "/*")
				trimmed = strings.TrimSuffix(trimmed, "*/")
				trimmed = strings.TrimSpace(trimmed)
			}
			if !strings.HasPrefix(trimmed, "revive:") {
				continue
			}
			// Now trimmed is like "revive:disable", "revive:disable:rule", "revive:disable-next-line", etc.
			directivePart := strings.TrimPrefix(trimmed, "revive:")
			// directivePart can be "disable", "enable", "disable-next-line", "disable-line", "disable:rule", "enable:rule", "disable-next-line:rule", etc.
			// Split by colon to get action and rules?
			// Actions: disable, enable, disable-next-line, disable-line

			// For simplicity, parse
			var action string
			var rulePart string
			if strings.Contains(directivePart, ":") {
				parts := strings.SplitN(directivePart, ":", 2)
				action = parts[0]
				rulePart = parts[1]
				// rulePart may itself contain further colons? But spec says disable:rule-name
				// For next-line with rule: disable-next-line:rule-name
				// So first part is action, second is rule list (comma separated?)
			} else {
				action = directivePart
				rulePart = ""
			}

			// Normalize action
			// action can be "disable", "enable", "disable-next-line", "disable-line"
			// According to README: //revive:disable, //revive:enable, //revive:disable-next-line, //revive:disable:rule-name, //revive:enable:rule-name
			// We also observed //revive:disable-line
			// So handle

			rulesList := []string{}
			if rulePart != "" {
				// rulePart could be like "var-declaration" or "rule-name" or multiple separated by comma?
				// We'll split by comma and space
				for _, r := range strings.Split(rulePart, ",") {
					r = strings.TrimSpace(r)
					if r != "" {
						rulesList = append(rulesList, r)
					}
				}
			}

			switch action {
			case "disable":
				if len(rulesList) == 0 {
					globalDisabledAll = true
					// Also mark all future lines as disabled until enable
					// We'll need to handle line-by-line later
				} else {
					for _, rr := range rulesList {
						globalDisabled[rr] = true
					}
				}
			case "enable":
				if len(rulesList) == 0 {
					globalDisabledAll = false
					globalDisabled = make(map[string]bool)
				} else {
					for _, rr := range rulesList {
						delete(globalDisabled, rr)
					}
				}
			case "disable-next-line":
				targetLine := line + 1
				if len(rulesList) == 0 {
					disabledAllPerLine[targetLine] = true
				} else {
					if disabledRulesPerLine[targetLine] == nil {
						disabledRulesPerLine[targetLine] = make(map[string]bool)
					}
					for _, rr := range rulesList {
						disabledRulesPerLine[targetLine][rr] = true
					}
				}
			case "disable-line":
				// Disables current line
				targetLine := line
				if len(rulesList) == 0 {
					disabledAllPerLine[targetLine] = true
				} else {
					if disabledRulesPerLine[targetLine] == nil {
						disabledRulesPerLine[targetLine] = make(map[string]bool)
					}
					for _, rr := range rulesList {
						disabledRulesPerLine[targetLine][rr] = true
					}
				}
			}
		}
	}

	// Also need to handle //revive:disable comments that affect lines after them until enable
	// Our globalDisabled handling already tracks, but we need to apply per line

	// We'll iterate through AST and for each relevant node that could produce failure, check if disabled

	var failures []Failure

	// Helper to check if rule disabled at given line
	isDisabled := func(line int, rule string) bool {
		if disabledAllPerLine[line] {
			return true
		}
		if m, ok := disabledRulesPerLine[line]; ok {
			if m[rule] {
				return true
			}
			// If disabledAllPerLine false but map exists, check?
		}
		if globalDisabledAll {
			return true
		}
		if globalDisabled[rule] {
			return true
		}
		return false
	}

	// Rule: var-declaration
	if _, enabled := enabledRules["var-declaration"]; enabled {
		// Walk file for var declarations with explicit type
		ast.Inspect(file, func(n ast.Node) bool {
			// Look for GenDecl with VAR token
			gen, ok := n.(*ast.GenDecl)
			if !ok {
				return true
			}
			if gen.Tok != token.VAR {
				return true
			}
			for _, spec := range gen.Specs {
				vs, ok := spec.(*ast.ValueSpec)
				if !ok {
					continue
				}
				if vs.Type == nil {
					continue
				}
				if len(vs.Values) == 0 {
					continue
				}
				// Check if type can be inferred
				// For simplicity, if type is present and value is present, report
				// But need to avoid cases where type is needed? The original rule is more complex, but we will report all var declarations with explicit type and initial value
				for i, name := range vs.Names {
					// Get position of name? Original reports position of type? Let's check earlier: "main.go:4:8" for var x int = 1 – column 8 corresponds to start of type? Let's check
					// In " var x int = 1", var is at col 2? Let's see ascii: space, var, space, x, space, int... Actually need to calculate
					// But we will report position of name's type? Simpler: report position of spec type
					pos := fset.Position(vs.Type.Pos())
					line := pos.Line
					if isDisabled(line, "var-declaration") {
						continue
					}
					// Also check if name line disabled
					namePos := fset.Position(name.Pos())
					if isDisabled(namePos.Line, "var-declaration") {
						continue
					}
					// Determine confidence: 0.8
					// Severity: use config
					severity := getSeverity(cfg, enabledRules, "var-declaration")
					confidence := getConfidence(cfg, enabledRules, "var-declaration", 0.8)

					// Get offset
					startOffset := fset.Position(vs.Type.Pos()).Offset
					endOffset := fset.Position(vs.Type.End()).Offset

					// For replacement line empty
					fail := Failure{
						Severity:       severity,
						FailureMessage: "should omit type " + fmt.Sprintf("%s", vs.Type) + " from declaration of var " + name.Name + "; it will be inferred from the right-hand side",
						RuleName:       "var-declaration",
						Category:       "type-inference",
						Confidence:     confidence,
						Position: Position{
							Start: Pos{
								Filename: filePath,
								Offset:   fset.Position(vs.Names[i].Pos()).Offset, // Actually original start is at type? Let's use name pos? Need to check earlier JSON: Start Filename main.go Offset 57 Line 4 Column 8, End Offset 60 Line 4 Column 11
								// In our earlier example: main.go with " var x int = 1" – offset 57 col 8. Let's compute: That file had package main is main etc. The var line is " var x int = 1". The type "int" starts at col 8? Let's test: " var x int = 1" – characters: 1:space,2:v,3:a,4:r,5:space,6:x,7:space,8:i,9:n,10:t... So col 8 is start of "int". So Start should be type start, End should be type end.
								// So we need to set Start to Type.Pos()
								// But we also need to set End to Type.End()
								// Let's use that.
								// We'll correct below
							},
							End: Pos{},
						},
						ReplacementLine: "",
					}
					// Actually set correctly
					start := fset.Position(vs.Type.Pos())
					end := fset.Position(vs.Type.End())
					fail.Position.Start = Pos{
						Filename: filePath,
						Offset:   start.Offset,
						Line:     start.Line,
						Column:   start.Column,
					}
					fail.Position.End = Pos{
						Filename: filePath,
						Offset:   end.Offset,
						Line:     end.Line,
						Column:   end.Column,
					}
					// Message: original uses actual type string, but we can get via fmt.Sprintf of type expression? For "int" it's "int"
					// Use type string from source: we can extract via string representation
					// For simplicity, use vs.Type as string via fmt? We'll try to get source snippet
					typeStr := string(src[start.Offset:end.Offset])
					fail.FailureMessage = fmt.Sprintf("should omit type %s from declaration of var %s; it will be inferred from the right-hand side", typeStr, name.Name)

					failures = append(failures, fail)
				}
			}
			return true
		})
	}

	// Rule: package-comments
	if _, enabled := enabledRules["package-comments"]; enabled {
		// Check if file has package comment
		// If file.Doc is nil, then no package comment
		hasComment := false
		if file.Doc != nil && len(file.Doc.List) > 0 {
			hasComment = true
		}
		if !hasComment {
			// Check if disabled
			line := 1
			if !isDisabled(line, "package-comments") {
				pos := fset.Position(file.Package)
				// Original reports Position Start at package keyword? Actually earlier JSON: Start Filename main.go Offset 0 Line 1 Column 1, End Offset 12 Line 1 Column 13 for "package main"
				// So start is at package keyword line 1 col 1
				// We'll use file.Package pos
				pkgPos := fset.Position(file.Package)
				// To get offset 0?
				// The file starts with "package" at offset 0
				// So use pkgPos
				severity := getSeverity(cfg, enabledRules, "package-comments")
				confidence := getConfidence(cfg, enabledRules, "package-comments", 1)

				// End position: package clause end: "package main" length? Original End at column 13 for "package main" (12 chars + 1?). Let's calculate: "package main" is 12 chars, column 13 is after? So end column is start+len?
				// We'll use file.Name pos for end? Actually package clause includes package name. Let's use file.Name.End()
				endPos := fset.Position(file.Name.End())

				fail := Failure{
					Severity:       severity,
					FailureMessage: "should have a package comment",
					RuleName:       "package-comments",
					Category:       "comments",
					Confidence:     confidence,
					Position: Position{
						Start: Pos{
							Filename: filePath,
							Offset:   pkgPos.Offset,
							Line:     pkgPos.Line,
							Column:   pkgPos.Column,
						},
						End: Pos{
							Filename: filePath,
							Offset:   fset.Position(file.Name.End()).Offset,
							Line:     endPos.Line,
							Column:   endPos.Column + 1, // +1 to match original?
						},
					},
					ReplacementLine: "",
				}
				// Adjust end to match original: In example, Start Offset 0 Line 1 Column1, End Offset 12 Line1 Column13 for "package main" (12 chars)
				// So End Offset should be start + len("package main")? But we can compute from source
				// Let's find "package" clause in source: from file.Package to file.Name.End()
				// That would be "package main"
				startOffset := pkgPos.Offset
				endOffset := fset.Position(file.Name.End()).Offset
				// The source slice from startOffset to endOffset is "package main"
				// In original, End Offset is 12 for that string (len 12)
				// So our endOffset should be correct
				// But Column: Start Column 1, End Column 13 (12+1)
				// So we need to compute column as start column + len
				// We'll set End Column as Start Column + (endOffset - startOffset)
				fail.Position.End.Offset = endOffset
				// Use file.Package line for start
				// Actually pkgPos already
				// Let's compute line/col for end based on start + length? For simplicity, use fset for end pos but adjust column
				fail.Position.Start = Pos{
					Filename: filePath,
					Offset:   startOffset,
					Line:     1,
					Column:   1,
				}
				// Find line 1 content
				// But for simplicity, use token position
				// We'll set end line same as start line
				fail.Position.End = Pos{
					Filename: filePath,
					Offset:   endOffset,
					Line:     1,
					Column:   1 + (endOffset - startOffset),
				}

				failures = append(failures, fail)
			}
		}
	}

	// Rule: exported
	if _, enabled := enabledRules["exported"]; enabled {
		// Check exported functions, types, etc without comments
		// Iterate over decls
		for _, decl := range file.Decls {
			gen, ok := decl.(*ast.GenDecl)
			if ok {
				// Check for exported types, vars, consts
				// For type declarations
				if gen.Tok == token.TYPE {
					for _, spec := range gen.Specs {
						ts, ok := spec.(*ast.TypeSpec)
						if !ok {
							continue
						}
						if !ts.Name.IsExported() {
							continue
						}
						// Check if has doc
						hasDoc := false
						if ts.Doc != nil && len(ts.Doc.List) > 0 {
							hasDoc = true
						}
						if gen.Doc != nil && len(gen.Doc.List) > 0 {
							hasDoc = true
						}
						if hasDoc {
							continue
						}
						// Check disabled
						pos := fset.Position(ts.Pos())
						if isDisabled(pos.Line, "exported") {
							continue
						}
						severity := getSeverity(cfg, enabledRules, "exported")
						confidence := getConfidence(cfg, enabledRules, "exported", 1)

						start := fset.Position(ts.Pos())
						end := fset.Position(ts.End())
						fail := Failure{
							Severity:       severity,
							FailureMessage: fmt.Sprintf("exported type %s should have comment or be unexported", ts.Name.Name),
							RuleName:       "exported",
							Category:       "comments",
							Confidence:     confidence,
							Position: Position{
								Start: Pos{Filename: filePath, Offset: start.Offset, Line: start.Line, Column: start.Column},
								End:   Pos{Filename: filePath, Offset: end.Offset, Line: end.Line, Column: end.Column},
							},
						}
						failures = append(failures, fail)
					}
				}
				// For const/var, check exported names
				if gen.Tok == token.CONST || gen.Tok == token.VAR {
					for _, spec := range gen.Specs {
						vs, ok := spec.(*ast.ValueSpec)
						if !ok {
							continue
						}
						for _, name := range vs.Names {
							if !name.IsExported() {
								continue
							}
							hasDoc := false
							if vs.Doc != nil && len(vs.Doc.List) > 0 {
								hasDoc = true
							}
							if gen.Doc != nil && len(gen.Doc.List) > 0 {
								hasDoc = true
							}
							if hasDoc {
								continue
							}
							pos := fset.Position(name.Pos())
							if isDisabled(pos.Line, "exported") {
								continue
							}
							severity := getSeverity(cfg, enabledRules, "exported")
							confidence := getConfidence(cfg, enabledRules, "exported", 1)
							start := fset.Position(name.Pos())
							end := fset.Position(name.End())
							fail := Failure{
								Severity:       severity,
								FailureMessage: fmt.Sprintf("exported var %s should have comment or be unexported", name.Name),
								RuleName:       "exported",
								Category:       "comments",
								Confidence:     confidence,
								Position: Position{
									Start: Pos{Filename: filePath, Offset: start.Offset, Line: start.Line, Column: start.Column},
									End:   Pos{Filename: filePath, Offset: end.Offset, Line: end.Line, Column: end.Column},
								},
							}
							failures = append(failures, fail)
						}
					}
				}
			}
			fn, ok := decl.(*ast.FuncDecl)
			if ok {
				if fn.Name == nil {
					continue
				}
				if !fn.Name.IsExported() {
					continue
				}
				// Check if method or function
				// If it's a function, check doc
				hasDoc := false
				if fn.Doc != nil && len(fn.Doc.List) > 0 {
					hasDoc = true
				}
				if hasDoc {
					continue
				}
				pos := fset.Position(fn.Pos())
				if isDisabled(pos.Line, "exported") {
					continue
				}
				severity := getSeverity(cfg, enabledRules, "exported")
				confidence := getConfidence(cfg, enabledRules, "exported", 1)
				start := fset.Position(fn.Pos())
				end := fset.Position(fn.End())
				// Failure message: "exported function Foo should have comment or be unexported"
				// Determine if method or function
				kind := "function"
				if fn.Recv != nil {
					kind = "method"
				}
				msg := fmt.Sprintf("exported %s %s should have comment or be unexported", kind, fn.Name.Name)
				fail := Failure{
					Severity:       severity,
					FailureMessage: msg,
					RuleName:       "exported",
					Category:       "comments",
					Confidence:     confidence,
					Position: Position{
						Start: Pos{Filename: filePath, Offset: start.Offset, Line: start.Line, Column: start.Column},
						End:   Pos{Filename: filePath, Offset: end.Offset, Line: end.Line, Column: end.Column},
					},
				}
				failures = append(failures, fail)
			}
		}
	}

	// Rule: dot-imports
	if _, enabled := enabledRules["dot-imports"]; enabled {
		for _, imp := range file.Imports {
			if imp.Name != nil && imp.Name.Name == "." {
				pos := fset.Position(imp.Pos())
				if isDisabled(pos.Line, "dot-imports") {
					continue
				}
				severity := getSeverity(cfg, enabledRules, "dot-imports")
				confidence := getConfidence(cfg, enabledRules, "dot-imports", 1)
				start := fset.Position(imp.Pos())
				end := fset.Position(imp.End())
				fail := Failure{
					Severity:       severity,
					FailureMessage: "should not use dot imports",
					RuleName:       "dot-imports",
					Category:       "imports",
					Confidence:     confidence,
					Position: Position{
						Start: Pos{Filename: filePath, Offset: start.Offset, Line: start.Line, Column: start.Column},
						End:   Pos{Filename: filePath, Offset: end.Offset, Line: end.Line, Column: end.Column},
					},
				}
				failures = append(failures, fail)
			}
		}
	}

	// Rule: blank-imports (check _ imports?)
	// We'll skip detailed, but implement basic
	if _, enabled := enabledRules["blank-imports"]; enabled {
		// Original seems to not report blank imports for simple case? We saw blank-imports didn't trigger with default? Let's still implement placeholder
		for _, imp := range file.Imports {
			if imp.Name != nil && imp.Name.Name == "_" {
				// Check if import is actually used? But we will not check usage, just report if import is blank and not used? For simplicity, report always? However original didn't report for simple blank import earlier
				// Let's check: In earlier test, blank-imports rule didn't trigger for import _ "fmt" – maybe it only triggers for certain cases?
				// We'll not report to avoid false positives
			}
		}
	}

	// Rule: unused-parameter
	if _, enabled := enabledRules["unused-parameter"]; enabled {
		// Find functions with unused parameters
		for _, decl := range file.Decls {
			fn, ok := decl.(*ast.FuncDecl)
			if !ok {
				continue
			}
			if fn.Type.Params == nil {
				continue
			}
			// Collect param names
			used := make(map[string]bool)
			// Walk function body to find used identifiers
			if fn.Body != nil {
				ast.Inspect(fn.Body, func(n ast.Node) bool {
					if ident, ok := n.(*ast.Ident); ok {
						used[ident.Name] = true
					}
					return true
				})
			}
			for _, field := range fn.Type.Params.List {
				for _, name := range field.Names {
					if name.Name == "_" {
						continue
					}
					if !used[name.Name] {
						// Check if used as _?
						pos := fset.Position(name.Pos())
						if isDisabled(pos.Line, "unused-parameter") {
							continue
						}
						severity := getSeverity(cfg, enabledRules, "unused-parameter")
						confidence := getConfidence(cfg, enabledRules, "unused-parameter", 1)
						start := fset.Position(name.Pos())
						end := fset.Position(name.End())
						fail := Failure{
							Severity:       severity,
							FailureMessage: fmt.Sprintf("parameter '%s' seems to be unused, consider removing or renaming it as _", name.Name),
							RuleName:       "unused-parameter",
							Category:       "bad practice",
							Confidence:     confidence,
							Position: Position{
								Start: Pos{Filename: filePath, Offset: start.Offset, Line: start.Line, Column: start.Column},
								End:   Pos{Filename: filePath, Offset: end.Offset, Line: end.Line, Column: end.Column},
							},
						}
						failures = append(failures, fail)
					}
				}
			}
		}
	}

	// Rule: receiver-naming
	if _, enabled := enabledRules["receiver-naming"]; enabled {
		// Track receiver names per type
		receiverNames := make(map[string]string) // type -> name
		for _, decl := range file.Decls {
			fn, ok := decl.(*ast.FuncDecl)
			if !ok {
				continue
			}
			if fn.Recv == nil || len(fn.Recv.List) == 0 {
				continue
			}
			recvField := fn.Recv.List[0]
			if len(recvField.Names) == 0 {
				continue
			}
			recvName := recvField.Names[0].Name
			// Get type name
			var typeName string
			switch t := recvField.Type.(type) {
			case *ast.StarExpr:
				if ident, ok := t.X.(*ast.Ident); ok {
					typeName = ident.Name
				}
			case *ast.Ident:
				typeName = t.Name
			}
			if typeName == "" {
				continue
			}
			if prev, ok := receiverNames[typeName]; ok {
				if prev != recvName {
					pos := fset.Position(fn.Pos())
					if isDisabled(pos.Line, "receiver-naming") {
						continue
					}
					severity := getSeverity(cfg, enabledRules, "receiver-naming")
					confidence := getConfidence(cfg, enabledRules, "receiver-naming", 1)
					start := fset.Position(fn.Pos())
					end := fset.Position(fn.End())
					fail := Failure{
						Severity:       severity,
						FailureMessage: fmt.Sprintf("receiver name %s should be consistent with previous receiver name %s for %s", recvName, prev, typeName),
						RuleName:       "receiver-naming",
						Category:       "naming",
						Confidence:     confidence,
						Position: Position{
							Start: Pos{Filename: filePath, Offset: start.Offset, Line: start.Line, Column: start.Column},
							End:   Pos{Filename: filePath, Offset: end.Offset, Line: end.Line, Column: end.Column},
						},
					}
					failures = append(failures, fail)
				}
			} else {
				receiverNames[typeName] = recvName
			}
		}
	}

	// Rule: empty-block
	if _, enabled := enabledRules["empty-block"]; enabled {
		ast.Inspect(file, func(n ast.Node) bool {
			block, ok := n.(*ast.BlockStmt)
			if !ok {
				return true
			}
			if len(block.List) == 0 {
				// Check if it's if, for, etc? Original reports "this block is empty, you can remove it"
				pos := fset.Position(block.Pos())
				if isDisabled(pos.Line, "empty-block") {
					return true
				}
				severity := getSeverity(cfg, enabledRules, "empty-block")
				confidence := getConfidence(cfg, enabledRules, "empty-block", 1)
				start := fset.Position(block.Pos())
				end := fset.Position(block.End())
				fail := Failure{
					Severity:       severity,
					FailureMessage: "this block is empty, you can remove it",
					RuleName:       "empty-block",
					Category:       "style",
					Confidence:     confidence,
					Position: Position{
						Start: Pos{Filename: filePath, Offset: start.Offset, Line: start.Line, Column: start.Column},
						End:   Pos{Filename: filePath, Offset: end.Offset, Line: end.Line, Column: end.Column},
					},
				}
				failures = append(failures, fail)
			}
			return true
		})
	}

	// Rule: unreachable-code
	if _, enabled := enabledRules["unreachable-code"]; enabled {
		ast.Inspect(file, func(n ast.Node) bool {
			block, ok := n.(*ast.BlockStmt)
			if !ok {
				return true
			}
			// Check if after return, there is more code
			foundReturn := false
			for _, stmt := range block.List {
				if foundReturn {
					// There's unreachable code
					pos := fset.Position(stmt.Pos())
					if isDisabled(pos.Line, "unreachable-code") {
						continue
					}
					severity := getSeverity(cfg, enabledRules, "unreachable-code")
					confidence := getConfidence(cfg, enabledRules, "unreachable-code", 1)
					start := fset.Position(stmt.Pos())
					end := fset.Position(stmt.End())
					fail := Failure{
						Severity:       severity,
						FailureMessage: "unreachable code after this statement",
						RuleName:       "unreachable-code",
						Category:       "style",
						Confidence:     confidence,
						Position: Position{
							Start: Pos{Filename: filePath, Offset: start.Offset, Line: start.Line, Column: start.Column},
							End:   Pos{Filename: filePath, Offset: end.Offset, Line: end.Line, Column: end.Column},
						},
					}
					failures = append(failures, fail)
					break
				}
				if _, ok := stmt.(*ast.ReturnStmt); ok {
					foundReturn = true
				}
			}
			return true
		})
	}

	// Rule: indent-error-flow
	if _, enabled := enabledRules["indent-error-flow"]; enabled {
		ast.Inspect(file, func(n ast.Node) bool {
			ifStmt, ok := n.(*ast.IfStmt)
			if !ok {
				return true
			}
			if ifStmt.Else == nil {
				return true
			}
			// Check if if block ends with return
			if ifStmt.Body == nil {
				return true
			}
			if len(ifStmt.Body.List) == 0 {
				return true
			}
			last, ok := ifStmt.Body.List[len(ifStmt.Body.List)-1].(*ast.ReturnStmt)
			if !ok {
				// Also check if last is branch?
				return true
			}
			_ = last
			pos := fset.Position(ifStmt.Pos())
			if isDisabled(pos.Line, "indent-error-flow") {
				return true
			}
			severity := getSeverity(cfg, enabledRules, "indent-error-flow")
			confidence := getConfidence(cfg, enabledRules, "indent-error-flow", 1)
			start := fset.Position(ifStmt.Pos())
			end := fset.Position(ifStmt.End())
			fail := Failure{
				Severity:       severity,
				FailureMessage: "if block ends with a return statement, so drop this else and outdent its block",
				RuleName:       "indent-error-flow",
				Category:       "style",
				Confidence:     confidence,
				Position: Position{
					Start: Pos{Filename: filePath, Offset: start.Offset, Line: start.Line, Column: start.Column},
					End:   Pos{Filename: filePath, Offset: end.Offset, Line: end.Line, Column: end.Column},
				},
			}
			failures = append(failures, fail)
			return true
		})
	}

	// Rule: line-length-limit
	if rc, enabled := enabledRules["line-length-limit"]; enabled {
		limit := 80
		if len(rc.Arguments) > 0 {
			switch v := rc.Arguments[0].(type) {
			case int64:
				limit = int(v)
			case int:
				limit = v
			case float64:
				limit = int(v)
			}
		}
		// Read file lines
		lines := strings.Split(string(src), "\n")
		for i, line := range lines {
			if len(line) > limit {
				lineNum := i + 1
				if isDisabled(lineNum, "line-length-limit") {
					continue
				}
				severity := getSeverity(cfg, enabledRules, "line-length-limit")
				confidence := getConfidence(cfg, enabledRules, "line-length-limit", 1)
				// Position: Start at line, column 0, offset?
				// Compute offset
				offset := 0
				for j := 0; j < i; j++ {
					offset += len(lines[j]) + 1
				}
				fail := Failure{
					Severity:       severity,
					FailureMessage: fmt.Sprintf("line is %d characters, out of limit %d", len(line), limit),
					RuleName:       "line-length-limit",
					Category:       "style",
					Confidence:     confidence,
					Position: Position{
						Start: Pos{Filename: filePath, Offset: offset, Line: lineNum, Column: 0},
						End:   Pos{Filename: filePath, Offset: offset, Line: lineNum, Column: len(line)},
					},
				}
				failures = append(failures, fail)
			}
		}
	}

	// Rule: string-of-int
	if _, enabled := enabledRules["string-of-int"]; enabled {
		ast.Inspect(file, func(n ast.Node) bool {
			call, ok := n.(*ast.CallExpr)
			if !ok {
				return true
			}
			fun, ok := call.Fun.(*ast.Ident)
			if !ok {
				return true
			}
			if fun.Name != "string" {
				return true
			}
			if len(call.Args) != 1 {
				return true
			}
			// Check if arg is int literal or int variable? For simplicity, check if arg is int literal or identifier that could be int? We'll check if arg is basic lit int or ident
			// Original checks dubious conversion of int to string
			// We'll report for any arg that is integer literal or call that returns int? Simplify: if arg is int literal, or identifier, or call
			// For now, report if arg is not string literal
			arg := call.Args[0]
			// If arg is string literal, not report
			if lit, ok := arg.(*ast.BasicLit); ok {
				if lit.Kind == token.INT {
					pos := fset.Position(call.Pos())
					if isDisabled(pos.Line, "string-of-int") {
						return true
					}
					severity := getSeverity(cfg, enabledRules, "string-of-int")
					confidence := getConfidence(cfg, enabledRules, "string-of-int", 1)
					start := fset.Position(call.Pos())
					end := fset.Position(call.End())
					fail := Failure{
						Severity:       severity,
						FailureMessage: "dubious conversion of an integer into a string, use strconv.Itoa",
						RuleName:       "string-of-int",
						Category:       "",
						Confidence:     confidence,
						Position: Position{
							Start: Pos{Filename: filePath, Offset: start.Offset, Line: start.Line, Column: start.Column},
							End:   Pos{Filename: filePath, Offset: end.Offset, Line: end.Line, Column: end.Column},
						},
					}
					failures = append(failures, fail)
				}
			}
			return true
		})
	}

	// Additional rules can be added as needed but for now we have a subset

	// Handle comment directives for line disables also for same line: //revive:disable-line and disable-next-line already handled, but also need to handle inline comments like "var x int = 1 //revive:disable-line:var-declaration"
	// Our earlier parsing for lineDisable used comment's line as target, but for inline comments we need to check if comment is on same line as code
	// We already set targetLine = line for disable-line, which is comment line, not code line. But if comment is trailing on same line as code, its line number equals code line, so it should disable that line. Our implementation for disable-line uses targetLine = line (comment line) which would be same as code line for trailing comment, so it should work.
	// However for disable-next-line, we set targetLine = line+1, which is correct.

	// For global disable directives that appear in code, we applied globalDisabledAll and globalDisabled, but we need to apply them per line after directive until enable.
	// Our current isDisabled checks global state regardless of line ordering, which would disable all lines if globalDisabledAll ever set, even before disable directive. We need to track line-by-line global state.

	// Let's reimplement more accurately: we need to sort directives by line and apply in order.

	// For simplicity for now, we will assume directives are file-scoped and we just need to check if any disable directive exists before failure line and not yet enabled.

	// We'll rebuild disabled tracking properly:

	// Collect all disable/enable directives in order
	type dirEvent struct {
		line int
		action string
		rules []string
	}
	var events []dirEvent
	for _, cg := range file.Comments {
		for _, c := range cg.List {
			text := c.Text
			if !strings.Contains(text, "revive:") {
				continue
			}
			trimmed := strings.TrimSpace(text)
			if strings.HasPrefix(trimmed, "//") {
				trimmed = strings.TrimPrefix(trimmed, "//")
				trimmed = strings.TrimSpace(trimmed)
			} else if strings.HasPrefix(trimmed, "/*") {
				trimmed = strings.TrimPrefix(trimmed, "/*")
				trimmed = strings.TrimSuffix(trimmed, "*/")
				trimmed = strings.TrimSpace(trimmed)
			}
			if !strings.HasPrefix(trimmed, "revive:") {
				continue
			}
			directivePart := strings.TrimPrefix(trimmed, "revive:")
			var action, rulePart string
			if strings.Contains(directivePart, ":") {
				parts := strings.SplitN(directivePart, ":", 2)
				action = parts[0]
				rulePart = parts[1]
				// For actions like "disable-next-line", we already have action = "disable-next-line" and rulePart may be rule name
				// But if directive is "disable:var-declaration", action = "disable", rulePart = "var-declaration" – correct
				// However for "disable-next-line:var-declaration", action = "disable-next-line", rulePart = "var-declaration" – correct
			} else {
				action = directivePart
			}
			rulesList := []string{}
			if rulePart != "" {
				for _, r := range strings.Split(rulePart, ",") {
					r = strings.TrimSpace(r)
					if r != "" {
						rulesList = append(rulesList, r)
					}
				}
			}
			pos := fset.Position(c.Pos())
			// Only consider disable/enable for global
			if action == "disable" || action == "enable" {
				events = append(events, dirEvent{line: pos.Line, action: action, rules: rulesList})
			}
		}
	}
	sort.Slice(events, func(i, j int) bool { return events[i].line < events[j].line })

	// Now for each failure, determine if disabled at that line based on events before that line
	// We'll create a function to check
	checkGlobalDisabled := func(line int, rule string) bool {
		disabledAll := false
		disabled := make(map[string]bool)
		for _, ev := range events {
			if ev.line > line {
				break
			}
			if ev.action == "disable" {
				if len(ev.rules) == 0 {
					disabledAll = true
				} else {
					for _, r := range ev.rules {
						disabled[r] = true
					}
				}
			} else if ev.action == "enable" {
				if len(ev.rules) == 0 {
					disabledAll = false
					disabled = make(map[string]bool)
				} else {
					for _, r := range ev.rules {
						delete(disabled, r)
					}
				}
			}
		}
		if disabledAll {
			return true
		}
		if disabled[rule] {
			return true
		}
		return false
	}

	// Now filter failures based on global disable state + per-line disables already considered (but per-line we already checked with isDisabled)
	var finalFailures []Failure
	for _, f := range failures {
		line := f.Position.Start.Line
		if isDisabled(line, f.RuleName) {
			continue
		}
		if checkGlobalDisabled(line, f.RuleName) {
			continue
		}
		finalFailures = append(finalFailures, f)
	}

	return finalFailures, nil
}

func getSeverity(cfg *Config, enabledRules map[string]RuleConfig, rule string) string {
	// Check rule-specific severity
	if rc, ok := enabledRules[rule]; ok {
		if rc.Severity != "" {
			return rc.Severity
		}
	}
	// Check global severity
	if cfg.Severity != "" {
		return cfg.Severity
	}
	if cfg.Conf.Severity != "" {
		return cfg.Conf.Severity
	}
	return "warning"
}

func getConfidence(cfg *Config, enabledRules map[string]RuleConfig, rule string, defaultConf float64) float64 {
	if rc, ok := enabledRules[rule]; ok {
		if rc.Confidence != nil {
			return *rc.Confidence
		}
	}
	// Global confidence? Not per rule, but threshold
	return defaultConf
}

func formatFailures(formatter string, failures []Failure, cfg *Config) ([]byte, error) {
	switch formatter {
	case "default":
		// Each failure as "filename:line:column: message"
		// Original sorts? We already sorted globally, but original default seems not sorted strictly, but we will use our sorted list
		// Also need to match exact output: for default, each line is "file:line:col: message"
		var buf bytes.Buffer
		for _, f := range failures {
			// f.Position.Start.Filename, Line, Column, FailureMessage
			buf.WriteString(fmt.Sprintf("%s:%d:%d: %s\n", f.Position.Start.Filename, f.Position.Start.Line, f.Position.Start.Column, f.FailureMessage))
		}
		return buf.Bytes(), nil
	case "plain":
		var buf bytes.Buffer
		for _, f := range failures {
			buf.WriteString(fmt.Sprintf("%s:%d:%d: %s https://revive.run/r#%s\n", f.Position.Start.Filename, f.Position.Start.Line, f.Position.Start.Column, f.FailureMessage, f.RuleName))
		}
		return buf.Bytes(), nil
	case "unix":
		var buf bytes.Buffer
		for _, f := range failures {
			buf.WriteString(fmt.Sprintf("%s:%d:%d: [%s] %s\n", f.Position.Start.Filename, f.Position.Start.Line, f.Position.Start.Column, f.RuleName, f.FailureMessage))
		}
		return buf.Bytes(), nil
	case "json":
		if len(failures) == 0 {
			return []byte("null"), nil
		}
		data, err := json.Marshal(failures)
		if err != nil {
			return nil, err
		}
		return data, nil
	case "ndjson":
		if len(failures) == 0 {
			return []byte(""), nil
		}
		var buf bytes.Buffer
		for _, f := range failures {
			b, _ := json.Marshal(f)
			buf.Write(b)
			buf.WriteString("\n")
		}
		// Original ndjson ends with extra newline? We saw blank line after each json object plus an extra newline at end
		// In earlier capture, ndjson had each object on its own line with no extra blank line at end, but there was an extra newline after last object? Let's check: earlier output showed two lines each with json and then blank line. We'll output with newline after each, no extra blank? Actually we observed an extra blank line (empty line) after ndjson output? In capture, there was blank line after. But let's output exactly as we do: each line with \n, and no extra trailing newline? Our buf will have newline after each, including last, but not extra blank line. In earlier capture, there was an extra blank line (i.e., two newlines?). Let's check: earlier ndjson output had two JSON lines and then blank line (one extra \n). Our buf with two lines each ending with \n will have one trailing \n, not two. The extra blank line observed might be from our echo separator. Let's keep single newline per object.
		return buf.Bytes(), nil
	case "friendly":
		if len(failures) == 0 {
			return []byte(""), nil
		}
		var buf bytes.Buffer
		// Group by? Original friendly prints each failure as:
		//   ⚠  https://revive.run/r#rule  message
		//   filename:line:column
		// Blank line between
		// At end summary:
		// ⚠  N problems (0 errors, M warnings)
		// Blank line
		// Warnings:
		//   count  rule
		// For each rule
		// Blank line? Actually earlier friendly had blank line after summary? Let's capture precisely

		// We need to sort failures for friendly? Original seemed sorted by filename? In earlier multi-file test, friendly sorted by filename? It printed sub/a.go first, then main.go. That is alphabetical. So we should sort by filename for friendly.

		// For our implementation, we already sorted by filename globally, so use that.

		// Count errors vs warnings
		errorCount := 0
		warningCount := 0
		ruleCounts := make(map[string]int)
		for _, f := range failures {
			if f.Severity == "error" {
				errorCount++
			} else {
				warningCount++
			}
			ruleCounts[f.RuleName]++
		}

		for _, f := range failures {
			// The warning symbol is "⚠" with two spaces before? In original, it was "  ⚠  https://..."
			buf.WriteString(fmt.Sprintf("  ⚠  https://revive.run/r#%s  %s\n", f.RuleName, f.FailureMessage))
			buf.WriteString(fmt.Sprintf("  %s:%d:%d\n", f.Position.Start.Filename, f.Position.Start.Line, f.Position.Start.Column))
			buf.WriteString("\n")
		}
		total := len(failures)
		buf.WriteString(fmt.Sprintf("⚠ %d problems (%d errors, %d warnings)\n", total, errorCount, warningCount))
		buf.WriteString("\n")
		buf.WriteString("Warnings:\n")
		// Sort rule counts by rule name? Original sorted by count? In earlier example with 3 var-declaration, it printed only one line. With 2 var-declaration and 1 exported, it printed var-declaration first (2) then exported (1). So sorted by count descending? Or alphabetical? In that example, var-declaration (2) before exported (1) – count descending. In example with 5 problems (3 var-declaration, 2 exported), it printed var-declaration first (3) then exported (2) – again count descending.
		// So sort ruleCounts by count descending, then by name?
		type rc struct {
			name  string
			count int
		}
		var rcs []rc
		for n, c := range ruleCounts {
			rcs = append(rcs, rc{n, c})
		}
		sort.Slice(rcs, func(i, j int) bool {
			if rcs[i].count != rcs[j].count {
				return rcs[i].count > rcs[j].count
			}
			return rcs[i].name < rcs[j].name
		})
		for _, r := range rcs {
			buf.WriteString(fmt.Sprintf("  %d  %s\n", r.count, r.name))
		}
		buf.WriteString("\n")
		return buf.Bytes(), nil
	case "stylish":
		if len(failures) == 0 {
			return []byte(""), nil
		}
		var buf bytes.Buffer
		// Group by file
		groups := make(map[string][]Failure)
		var fileOrder []string
		seenFiles := make(map[string]bool)
		for _, f := range failures {
			fn := f.Position.Start.Filename
			if !seenFiles[fn] {
				seenFiles[fn] = true
				fileOrder = append(fileOrder, fn)
			}
			groups[fn] = append(groups[fn], f)
		}
		// Sort fileOrder? Original stylish groups seemed sorted by file name? In earlier multi-file test, stylish printed main.go first, then sub/a.go – which is alphabetical? main.go < sub/a.go? Actually "main.go" < "sub/a.go" alphabetically yes (m vs s). In earlier test with pkg/a and pkg/b and main.go, stylish printed main.go first, then pkg/a, then pkg/b – again alphabetical? main.go, pkg/a, pkg/b – yes alphabetical.
		sort.Strings(fileOrder)

		for _, fn := range fileOrder {
			buf.WriteString(fmt.Sprintf("%s\n", fn))
			// Sort failures within file by line, col
			fails := groups[fn]
			sort.Slice(fails, func(i, j int) bool {
				if fails[i].Position.Start.Line != fails[j].Position.Start.Line {
					return fails[i].Position.Start.Line < fails[j].Position.Start.Line
				}
				return fails[i].Position.Start.Column < fails[j].Position.Start.Column
			})
			for _, f := range fails {
				buf.WriteString(fmt.Sprintf("  (%d, %d)  https://revive.run/r#%s  %s\n", f.Position.Start.Line, f.Position.Start.Column, f.RuleName, f.FailureMessage))
			}
			buf.WriteString("\n")
		}
		// Summary line: " ✖ N problems (0 errors) (M warnings)"
		errorCount := 0
		warningCount := 0
		for _, f := range failures {
			if f.Severity == "error" {
				errorCount++
			} else {
				warningCount++
			}
		}
		buf.WriteString("\n")
		buf.WriteString(fmt.Sprintf(" ✖ %d problems (%d errors) (%d warnings)\n", len(failures), errorCount, warningCount))
		return buf.Bytes(), nil
	case "checkstyle":
		type CheckstyleError struct {
			Line     int    `xml:"line,attr"`
			Column   int    `xml:"column,attr"`
			Message  string `xml:"message,attr"`
			Severity string `xml:"severity,attr"`
			Source   string `xml:"source,attr"`
		}
		type CheckstyleFile struct {
			Name   string            `xml:"name,attr"`
			Errors []CheckstyleError `xml:"error"`
		}
