func loadConfigWithMeta(explicitPath string) (*Config, bool, error) {
	// Returns config, whether file was loaded, error
	cfg := &Config{
		Rule: make(map[string]RuleConfig),
	}
	cfg.Confidence = 0.8
	cfg.Severity = "warning"

	var pathToLoad string
	fileLoaded := false
	if explicitPath != "" {
		pathToLoad = explicitPath
		if _, err := os.Stat(pathToLoad); err != nil {
			return nil, false, fmt.Errorf("cannot read the config file")
		}
		fileLoaded = true
	} else {
		xdg := os.Getenv("XDG_CONFIG_HOME")
		home := os.Getenv("HOME")
		if xdg != "" {
			candidate := filepath.Join(xdg, "revive.toml")
			if _, err := os.Stat(candidate); err == nil {
				pathToLoad = candidate
				fileLoaded = true
			}
		}
		if !fileLoaded && home != "" {
			// Try $HOME/.config/revive.toml if XDG not set
			if xdg == "" {
				candidate := filepath.Join(home, ".config", "revive.toml")
				if _, err := os.Stat(candidate); err == nil {
					pathToLoad = candidate
					fileLoaded = true
				}
			}
			if !fileLoaded {
				candidate := filepath.Join(home, "revive.toml")
				if _, err := os.Stat(candidate); err == nil {
					pathToLoad = candidate
					fileLoaded = true
				}
			}
		}
		if !fileLoaded {
			// No config file, return default config but fileLoaded false
			return cfg, false, nil
		}
	}

	// Load file
	data, err := os.ReadFile(pathToLoad)
	if err != nil {
		return nil, false, fmt.Errorf("cannot read the config file")
	}
	if len(bytes.TrimSpace(data)) == 0 {
		// Empty file – treat as loaded but with no rules (so enabledRules empty)
		return cfg, true, nil
	}
	var raw map[string]interface{}
	if _, err := toml.Decode(string(data), &raw); err != nil {
		return nil, true, err
	}
	if _, err := toml.Decode(string(data), cfg); err != nil {
		return nil, true, err
	}
	// Merge conf etc (same as before)
	// Simplified copy of previous logic
	if confRaw, ok := raw["conf"]; ok {
		if confMap, ok := confRaw.(map[string]interface{}); ok {
			if v, ok := confMap["severity"]; ok {
				if s, ok := v.(string); ok && cfg.Conf.Severity == "" {
					cfg.Conf.Severity = s
				}
			}
			if v, ok := confMap["confidence"]; ok {
				if f, ok := v.(float64); ok {
					cfg.Conf.Confidence = f
				}
			}
			if v, ok := confMap["errorCode"]; ok {
				switch val := v.(type) {
				case int64:
					cfg.Conf.ErrorCode = int(val)
				case float64:
					cfg.Conf.ErrorCode = int(val)
				}
			}
			if v, ok := confMap["warningCode"]; ok {
				switch val := v.(type) {
				case int64:
					cfg.Conf.WarningCode = int(val)
				case float64:
					cfg.Conf.WarningCode = int(val)
				}
			}
			if v, ok := confMap["ignoreGeneratedHeader"]; ok {
				if b, ok := v.(bool); ok {
					cfg.Conf.IgnoreGeneratedHeader = b
				}
			}
			if v, ok := confMap["exclude"]; ok {
				if arr, ok := v.([]interface{}); ok {
					for _, item := range arr {
						if s, ok := item.(string); ok {
							cfg.Conf.Exclude = append(cfg.Conf.Exclude, s)
						}
					}
				}
			}
		}
	}
	if cfg.Severity == "" && cfg.Conf.Severity != "" {
		cfg.Severity = cfg.Conf.Severity
	}
	if cfg.Confidence == 0 && cfg.Conf.Confidence != 0 {
		cfg.Confidence = cfg.Conf.Confidence
	}
	if cfg.ErrorCode == 0 && cfg.Conf.ErrorCode != 0 {
		cfg.ErrorCode = cfg.Conf.ErrorCode
	}
	if cfg.WarningCode == 0 && cfg.Conf.WarningCode != 0 {
		cfg.WarningCode = cfg.Conf.WarningCode
	}
	if !cfg.IgnoreGeneratedHeader && cfg.Conf.IgnoreGeneratedHeader {
		cfg.IgnoreGeneratedHeader = true
	}
	if len(cfg.Exclude) == 0 && len(cfg.Conf.Exclude) > 0 {
		cfg.Exclude = cfg.Conf.Exclude
	}

	if ruleRaw, ok := raw["rule"]; ok {
		if ruleMap, ok := ruleRaw.(map[string]interface{}); ok {
			for ruleName, ruleVal := range ruleMap {
				if rm, ok := ruleVal.(map[string]interface{}); ok {
					rc := RuleConfig{}
					if v, ok := rm["Disabled"]; ok {
						if b, ok := v.(bool); ok {
							rc.Disabled = b
						}
					}
					if v, ok := rm["disabled"]; ok {
						if b, ok := v.(bool); ok {
							rc.Disabled = b
						}
					}
					if v, ok := rm["Severity"]; ok {
						if s, ok := v.(string); ok {
							rc.Severity = s
						}
					}
					if v, ok := rm["severity"]; ok {
						if s, ok := v.(string); ok {
							rc.Severity = s
						}
					}
					if v, ok := rm["Confidence"]; ok {
						switch val := v.(type) {
						case float64:
							rc.Confidence = &val
						case int64:
							f := float64(val)
							rc.Confidence = &f
						}
					}
					if v, ok := rm["confidence"]; ok {
						switch val := v.(type) {
						case float64:
							rc.Confidence = &val
						case int64:
							f := float64(val)
							rc.Confidence = &f
						}
					}
					if v, ok := rm["Exclude"]; ok {
						if arr, ok := v.([]interface{}); ok {
							for _, item := range arr {
								if s, ok := item.(string); ok {
									rc.Exclude = append(rc.Exclude, s)
								}
							}
						}
					}
					if v, ok := rm["exclude"]; ok {
						if arr, ok := v.([]interface{}); ok {
							for _, item := range arr {
								if s, ok := item.(string); ok {
									rc.Exclude = append(rc.Exclude, s)
								}
							}
						}
					}
					if v, ok := rm["Arguments"]; ok {
						if arr, ok := v.([]interface{}); ok {
							rc.Arguments = arr
						}
					}
					if v, ok := rm["arguments"]; ok {
						if arr, ok := v.([]interface{}); ok {
							rc.Arguments = arr
						}
					}
					if existing, exists := cfg.Rule[ruleName]; exists {
						if rc.Severity != "" {
							existing.Severity = rc.Severity
						}
						if rc.Confidence != nil {
							existing.Confidence = rc.Confidence
						}
						if len(rc.Exclude) > 0 {
							existing.Exclude = rc.Exclude
						}
						if len(rc.Arguments) > 0 {
							existing.Arguments = rc.Arguments
						}
						if rc.Disabled {
							existing.Disabled = true
						}
						cfg.Rule[ruleName] = existing
					} else {
						cfg.Rule[ruleName] = rc
					}
				}
			}
		}
	}

	if err := validateRules(cfg.Rule); err != nil {
		return nil, true, err
	}

	return cfg, true, nil
}

