	}

	cfg, fileLoaded, err := loadConfigWithMeta(configPath)
	if err != nil {
		if strings.Contains(err.Error(), "cannot read the config file") {
			fmt.Fprintln(os.Stderr, "cannot read the config file")
			os.Exit(1)
		}
		if strings.Contains(err.Error(), "cannot find rule") {
			fmt.Fprintln(os.Stderr, err.Error())
			os.Exit(1)
		}
		if strings.Contains(err.Error(), "Expecting value") {
			fmt.Fprintln(os.Stderr, err.Error())
			os.Exit(1)
		}
		if strings.Contains(err.Error(), "toml:") {
			fmt.Fprintf(os.Stderr, "cannot parse the config file: %s\n", err.Error())
			os.Exit(1)
		}
		fmt.Fprintln(os.Stderr, err.Error())
		os.Exit(1)
	}

	args := flag.Args()
	if len(args) == 0 {
		args = []string{"./..."}
	}

	// Merge global excludes
	globalExclude := append([]string{}, cfg.Exclude...)
	// Note: cfg.Conf.Exclude already merged into cfg.Exclude in loader
	files, err := collectFiles(args, globalExclude, []string(excludePatterns))
	if err != nil {
		fmt.Fprintln(os.Stderr, err.Error())
		os.Exit(1)
	}

	// Determine enabled rules
	var enabledRules map[string]RuleConfig
	if !fileLoaded {
		// No config file found -> use default rules
		enabledRules = getDefaultRules()
	} else {
		if len(cfg.Rule) == 0 {
			// Config file loaded but no rules defined -> no rules enabled (matches original empty.toml behavior)
			enabledRules = make(map[string]RuleConfig)
		} else {
			enabledRules = make(map[string]RuleConfig)
			for name, rc := range cfg.Rule {
				if !rc.Disabled {
					enabledRules[name] = rc
				}
			}
		}
	}

	failures, err := lintFiles(files, cfg, enabledRules)
	if err != nil {
		fmt.Fprintln(os.Stderr, err.Error())
		os.Exit(1)
	}

	// Confidence filter: use cfg.Confidence (if 0 use 0.8? but we set default 0.8)
	threshold := cfg.Confidence
	if threshold == 0 {
		threshold = 0.8
		// But if config explicitly sets confidence 0, we should not filter? Original with confidence 0 in config meant threshold 0 (no filtering). How to distinguish? In loadConfig we set default 0.8 when not loaded? We need to handle.
		// We'll check if cfg has explicit confidence via raw? For now, if fileLoaded and raw had confidence 0, threshold 0 would be treated as default, which is wrong.
		// To handle, we will use cfg.Confidence if fileLoaded, else 0.8, but if fileLoaded and cfg.Confidence ==0 and raw didn't contain confidence, we use 0.8, else if raw contained confidence 0, use 0.
		// Our loader sets Confidence to 0.8 by default always. So when fileLoaded and config sets confidence =0, it would be 0. So threshold 0 would be 0, not default. So our check threshold==0 to set 0.8 is wrong for explicit 0.
		// Instead, we should keep threshold as cfg.Confidence, but if !fileLoaded, threshold=0.8
		// Let's adjust: if !fileLoaded, threshold=0.8, else threshold=cfg.Confidence
	}
	if !fileLoaded {
		threshold = 0.8
	} else {
		threshold = cfg.Confidence
	}

	filtered := filterByConfidence(failures, threshold)
	filtered = filterByRuleExclude(filtered, cfg)

	// Sort for deterministic output (except formatters that group)
	sort.Slice(filtered, func(i, j int) bool {
		if filtered[i].Position.Start.Filename != filtered[j].Position.Start.Filename {
			return filtered[i].Position.Start.Filename < filtered[j].Position.Start.Filename
		}
		if filtered[i].Position.Start.Line != filtered[j].Position.Start.Line {
			return filtered[i].Position.Start.Line < filtered[j].Position.Start.Line
		}
		if filtered[i].Position.Start.Column != filtered[j].Position.Start.Column {
			return filtered[i].Position.Start.Column < filtered[j].Position.Start.Column
		}
		return filtered[i].RuleName < filtered[j].RuleName
	})

	output, err := formatFailures(formatterName, filtered, cfg, enabledRules)
	if err != nil {
		fmt.Fprintf(os.Stderr, "formatting - getting formatter: %s\n", err.Error())
		os.Exit(1)
	}
	if len(output) > 0 {
		fmt.Print(string(output))
	}

	// Exit code
	exitCode := 0
	if setExitStatus {
		if len(filtered) > 0 {
			exitCode = 1
		}
	} else {
		hasError := false
		hasWarning := false
		for _, f := range filtered {
			if f.Severity == "error" {
				hasError = true
			} else {
				hasWarning = true
			}
		}
		if hasError {
			exitCode = cfg.ErrorCode
			if cfg.Conf.ErrorCode != 0 {
				// cfg.ErrorCode already includes conf merged, but if top-level not set, we use conf
				// Our merge already handled
			}
		} else if hasWarning {
			exitCode = cfg.WarningCode
		}
	}
	_ = maxOpenFiles
	os.Exit(exitCode)
}

func loadConfigWithMeta(explicitPath string) (*Config, bool, error) {
	cfg := &Config{
		Rule: make(map[string]RuleConfig),
	}
	cfg.Confidence = 0.8
	cfg.Severity = "warning"

	var pathToLoad string
	fileLoaded := false
	if explicitPath != "" {
		pathToLoad = explicitPath
		if _, err := os.Stat(pathToLoad); err != nil {
			return nil, false, fmt.Errorf("cannot read the config file")
		}
		fileLoaded = true
	} else {
		xdg := os.Getenv("XDG_CONFIG_HOME")
		home := os.Getenv("HOME")
		if xdg != "" {
			candidate := filepath.Join(xdg, "revive.toml")
			if _, err := os.Stat(candidate); err == nil {
				pathToLoad = candidate
				fileLoaded = true
			}
		}
		if !fileLoaded && home != "" {
			if xdg == "" {
				candidate := filepath.Join(home, ".config", "revive.toml")
				if _, err := os.Stat(candidate); err == nil {
					pathToLoad = candidate
					fileLoaded = true
				}
			}
			if !fileLoaded {
				candidate := filepath.Join(home, "revive.toml")
				if _, err := os.Stat(candidate); err == nil {
					pathToLoad = candidate
					fileLoaded = true
				}
			}
		}
		if !fileLoaded {
			return cfg, false, nil
		}
	}

	data, err := os.ReadFile(pathToLoad)
	if err != nil {
		return nil, false, fmt.Errorf("cannot read the config file")
	}
	if len(bytes.TrimSpace(data)) == 0 {
		// Empty file -> loaded but no rules
		// Keep cfg with empty Rule but fileLoaded true
		// Also need to parse confidence etc? Empty file has none, so keep defaults? But original empty file gave no failures, and confidence wouldn't matter. We'll return cfg with empty rules and fileLoaded true, but keep default confidence? Actually for empty file, original had no rules, so confidence filter irrelevant. We'll keep cfg.Confidence as 0? Let's set to 0 to indicate no filtering? But spec says empty config should have no rules, not default confidence. We'll set Confidence to 0 and let caller handle? However our earlier logic for threshold uses cfg.Confidence when fileLoaded. If empty file, we want no failures, so confidence filter doesn't matter. We'll leave Confidence as 0.8 default but since no rules, no failures.
		// To differentiate empty file case from file with no rules but with confidence set, we need to re-parse raw for confidence.
		// For empty file, we return cfg with Rule empty and fileLoaded true, but with Confidence 0.8? Actually original empty.toml with no rules gave null json, so no failures regardless of confidence. So returning with default confidence is fine.
		cfg.Rule = make(map[string]RuleConfig)
		return cfg, true, nil
	}

	var raw map[string]interface{}
	if _, err := toml.Decode(string(data), &raw); err != nil {
		return nil, true, err
	}
	// Decode into cfg for top-level fields (severity, confidence, etc) using same data
	if _, err := toml.Decode(string(data), cfg); err != nil {
		return nil, true, err
	}

	// Handle conf section merge
	if confRaw, ok := raw["conf"]; ok {
		if confMap, ok := confRaw.(map[string]interface{}); ok {
			if v, ok := confMap["severity"]; ok {
				if s, ok := v.(string); ok {
					if cfg.Conf.Severity == "" {
						cfg.Conf.Severity = s
					}
				}
			}
			if v, ok := confMap["confidence"]; ok {
				if f, ok := v.(float64); ok {
					cfg.Conf.Confidence = f
				} else if i, ok := v.(int64); ok {
					cfg.Conf.Confidence = float64(i)
				}
			}
			if v, ok := confMap["errorCode"]; ok {
				switch val := v.(type) {
				case int64:
					cfg.Conf.ErrorCode = int(val)
				case float64:
					cfg.Conf.ErrorCode = int(val)
				}
			}
			if v, ok := confMap["warningCode"]; ok {
				switch val := v.(type) {
				case int64:
					cfg.Conf.WarningCode = int(val)
				case float64:
					cfg.Conf.WarningCode = int(val)
				}
			}
			if v, ok := confMap["ignoreGeneratedHeader"]; ok {
				if b, ok := v.(bool); ok {
					cfg.Conf.IgnoreGeneratedHeader = b
				}
			}
			if v, ok := confMap["exclude"]; ok {
				if arr, ok := v.([]interface{}); ok {
					for _, item := range arr {
						if s, ok := item.(string); ok {
							cfg.Conf.Exclude = append(cfg.Conf.Exclude, s)
						}
					}
				}
			}
		}
	}

	// Merge top-level and conf: if top-level empty and conf has value, use conf
	if cfg.Severity == "" && cfg.Conf.Severity != "" {
		cfg.Severity = cfg.Conf.Severity
	}
	// For confidence, need to know if explicitly set. Since cfg.Confidence default 0.8, if file sets confidence 0, we would have 0. So we check raw for confidence key
	if _, ok := raw["confidence"]; !ok {
		if cfg.Conf.Confidence != 0 {
			cfg.Confidence = cfg.Conf.Confidence
		}
	}
	// If raw contains confidence, cfg.Confidence already set via Decode
	// For errorCode/warningCode: if top-level not set (0) and conf has, use conf
	if cfg.ErrorCode == 0 && cfg.Conf.ErrorCode != 0 {
		cfg.ErrorCode = cfg.Conf.ErrorCode
	}
	if cfg.WarningCode == 0 && cfg.Conf.WarningCode != 0 {
		cfg.WarningCode = cfg.Conf.WarningCode
	}
	if !cfg.IgnoreGeneratedHeader && cfg.Conf.IgnoreGeneratedHeader {
		cfg.IgnoreGeneratedHeader = true
	}
	if len(cfg.Exclude) == 0 && len(cfg.Conf.Exclude) > 0 {
		cfg.Exclude = cfg.Conf.Exclude
	}

	// Parse rules manually for case insensitivity
	if ruleRaw, ok := raw["rule"]; ok {
		if ruleMap, ok := ruleRaw.(map[string]interface{}); ok {
			// Ensure cfg.Rule exists
			if cfg.Rule == nil {
				cfg.Rule = make(map[string]RuleConfig)
			}
			for ruleName, ruleVal := range ruleMap {
				if rm, ok := ruleVal.(map[string]interface{}); ok {
					rc := cfg.Rule[ruleName] // get existing if any
					// Disabled
					if v, ok := rm["Disabled"]; ok {
						if b, ok := v.(bool); ok {
							rc.Disabled = b
						}
					}
					if v, ok := rm["disabled"]; ok {
						if b, ok := v.(bool); ok {
							rc.Disabled = b
						}
					}
					if v, ok := rm["Severity"]; ok {
						if s, ok := v.(string); ok {
							rc.Severity = s
						}
					}
					if v, ok := rm["severity"]; ok {
						if s, ok := v.(string); ok {
							rc.Severity = s
						}
					}
					if v, ok := rm["Confidence"]; ok {
						switch val := v.(type) {
						case float64:
							rc.Confidence = &val
						case int64:
							f := float64(val)
							rc.Confidence = &f
						}
					}
					if v, ok := rm["confidence"]; ok {
						switch val := v.(type) {
						case float64:
							rc.Confidence = &val
						case int64:
							f := float64(val)
							rc.Confidence = &f
						}
					}
					if v, ok := rm["Exclude"]; ok {
						if arr, ok := v.([]interface{}); ok {
							rc.Exclude = nil
							for _, item := range arr {
								if s, ok := item.(string); ok {
									rc.Exclude = append(rc.Exclude, s)
								}
							}
						}
					}
					if v, ok := rm["exclude"]; ok {
						if arr, ok := v.([]interface{}); ok {
							rc.Exclude = nil
							for _, item := range arr {
								if s, ok := item.(string); ok {
									rc.Exclude = append(rc.Exclude, s)
								}
							}
						}
					}
					if v, ok := rm["Arguments"]; ok {
						if arr, ok := v.([]interface{}); ok {
							rc.Arguments = arr
						}
					}
					if v, ok := rm["arguments"]; ok {
						if arr, ok := v.([]interface{}); ok {
							rc.Arguments = arr
						}
					}
					cfg.Rule[ruleName] = rc
				}
			}
		}
	}

	if err := validateRules(cfg.Rule); err != nil {
		return nil, true, err
	}

	return cfg, true, nil
}

