	valid := map[string]bool{
		"add-constant": true, "argument-limit": true, "atomic": true, "bare-return": true, "blank-imports": true,
		"bool-literal-in-expr": true, "call-to-gc": true, "comment-spacings": true, "confusing-naming": true,
		"confusing-results": true, "constant-logical-expr": true, "context-as-argument": true, "context-keys-type": true,
		"cyclomatic": true, "datarace": true, "deep-exit": true, "defer": true, "dot-imports": true,
		"duplicated-imports": true, "early-return": true, "empty-block": true, "error-naming": true,
		"error-return": true, "error-strings": true, "errorf": true, "exported": true, "file-header": true,
		"function-length": true, "function-result-limit": true, "get-return": true, "if-return": true,
		"import-alias-naming": true, "import-shadowing": true, "imports-blacklist": true, "increment-decrement": true,
		"indent-error-flow": true, "line-length-limit": true, "max-public-structs": true, "modifies-parameter": true,
		"modifies-value-receiver": true, "nested-structs": true, "optimize-operands-order": true, "package-comments": true,
		"range": true, "range-val-address": true, "range-val-in-closure": true, "receiver-naming": true,
		"redefines-builtin-id": true, "redundant-import-alias": true, "string-format": true, "string-of-int": true,
		"struct-tag": true, "superfluous-else": true, "time-date": true, "time-equal": true, "time-naming": true,
		"unchecked-type-assertion": true, "unconditional-recursion": true, "unexported-naming": true, "unexported-return": true,
		"unhandled-error": true, "unnecessary-format": true, "unnecessary-stmt": true, "unreachable-code": true,
		"unused-parameter": true, "unused-receiver": true, "use-any": true, "use-waitgroup-go": true,
		"useless-break": true, "useless-fallthrough": true, "var-declaration": true, "var-naming": true, "waitgroup-by-value": true,
		"enforce-map-style": true, "enforce-repeated-arg-type-style": true, "enforce-slice-style": true, "flag-parameter": true,
		"forbidden-call": true, "identical-branches": true, "banned-characters": true, "inefficient-map-lookup": true, "redundant-build-tag": true,
	}
	for name := range rules {
		if !valid[name] {
			return fmt.Errorf("initializing revive - getting lint rules: cannot find rule: %s", name)
