func collectFiles(patterns []string, globalExclude []string, flagExcludes []string) ([]string, error) {
	excludes := append([]string{}, globalExclude...)
	excludes = append(excludes, flagExcludes...)
	var files []string
	for _, pat := range patterns {
		if strings.Contains(pat, "...") {
			base := strings.TrimSuffix(pat, "/...")
			base = strings.TrimSuffix(base, "...")
			if base == "" || base == "." || base == "./" {
				base = "."
			}
			err := filepath.Walk(base, func(path string, info os.FileInfo, err error) error {
				if err != nil {
					return nil
				}
				if info.IsDir() {
					for _, ex := range excludes {
						if matchExclude(ex, path) {
							return filepath.SkipDir
						}
					}
					return nil
				}
				if !strings.HasSuffix(path, ".go") {
					return nil
				}
				for _, ex := range excludes {
					if matchExclude(ex, path) {
						return nil
					}
				}
				files = append(files, path)
				return nil
			})
			if err != nil {
				return nil, err
			}
		} else {
			if strings.HasSuffix(pat, ".go") {
				if _, err := os.Stat(pat); err == nil {
					excluded := false
					for _, ex := range excludes {
						if matchExclude(ex, pat) {
							excluded = true
							break
						}
					}
					if !excluded {
						files = append(files, pat)
					}
				} else {
					if info, err := os.Stat(pat); err == nil && info.IsDir() {
						entries, _ := os.ReadDir(pat)
						for _, e := range entries {
							if !e.IsDir() && strings.HasSuffix(e.Name(), ".go") {
								full := filepath.Join(pat, e.Name())
								excluded := false
								for _, ex := range excludes {
									if matchExclude(ex, full) {
										excluded = true
										break
									}
								}
								if !excluded {
									files = append(files, full)
								}
							}
						}
					}
				}
			} else {
				cleanPat := pat
				if strings.HasPrefix(cleanPat, "./") {
					cleanPat = cleanPat[2:]
				}
				if cleanPat == "." || cleanPat == "" {
					cleanPat = "."
				}
				if info, err := os.Stat(cleanPat); err == nil && info.IsDir() {
					entries, _ := os.ReadDir(cleanPat)
					for _, e := range entries {
						if !e.IsDir() && strings.HasSuffix(e.Name(), ".go") {
							full := filepath.Join(cleanPat, e.Name())
							excluded := false
							for _, ex := range excludes {
								if matchExclude(ex, full) {
									excluded = true
									break
								}
							}
							if !excluded {
								files = append(files, full)
							}
						}
					}
				} else {
					matches, err := filepath.Glob(pat)
					if err == nil {
						for _, m := range matches {
							if strings.HasSuffix(m, ".go") {
								if info, err := os.Stat(m); err == nil && !info.IsDir() {
									excluded := false
									for _, ex := range excludes {
										if matchExclude(ex, m) {
											excluded = true
											break
										}
									}
									if !excluded {
										files = append(files, m)
									}
								}
							} else {
								if info, err := os.Stat(m); err == nil && info.IsDir() {
									entries, _ := os.ReadDir(m)
									for _, e := range entries {
										if !e.IsDir() && strings.HasSuffix(e.Name(), ".go") {
											full := filepath.Join(m, e.Name())
											excluded := false
											for _, ex := range excludes {
												if matchExclude(ex, full) {
													excluded = true
													break
												}
											}
											if !excluded {
												files = append(files, full)
											}
										}
									}
								}
							}
						}
					}
				}
			}
		}
	}
	seen := make(map[string]bool)
	var uniq []string
	for _, f := range files {
		if !seen[f] {
			seen[f] = true
			uniq = append(uniq, f)
		}
	}
	return uniq, nil
}

func matchExclude(pattern, path string) bool {
	if strings.HasSuffix(pattern, "/...") {
		base := strings.TrimSuffix(pattern, "/...")
		if path == base || strings.HasPrefix(path, base+"/") {
			return true
		}
		return strings.HasPrefix(path, base)
	}
	if strings.Contains(pattern, "...") {
		base := strings.Split(pattern, "...")[0]
		return strings.HasPrefix(path, base)
	}
	if pattern == path {
		return true
	}
	if matched, _ := filepath.Match(pattern, path); matched {
		return true
	}
	if matched, _ := filepath.Match(pattern, filepath.Base(path)); matched {
		return true
	}
	if strings.HasPrefix(path, pattern+"/") {
		return true
	}
	return false
}

func filterByConfidence(failures []Failure, threshold float64) []Failure {
	if threshold == 0 {
		return failures
	}
	var out []Failure
	for _, f := range failures {
		if f.Confidence >= threshold {
			out = append(out, f)
		}
	}
	return out
}

func filterByRuleExclude(failures []Failure, cfg *Config) []Failure {
	var out []Failure
	for _, f := range failures {
		if rc, ok := cfg.Rule[f.RuleName]; ok {
			excluded := false
			for _, ex := range rc.Exclude {
				if matchExclude(ex, f.Position.Start.Filename) {
					excluded = true
					break
				}
			}
			if excluded {
				continue
			}
		}
		out = append(out, f)
	}
	return out
}

func lintFiles(files []string, cfg *Config, enabledRules map[string]RuleConfig) ([]Failure, error) {
	var all []Failure
	for _, fp := range files {
		if cfg.IgnoreGeneratedHeader {
			content, err := os.ReadFile(fp)
			if err == nil {
				lines := strings.Split(string(content), "\n")
				for i := 0; i < len(lines) && i < 5; i++ {
					if strings.Contains(lines[i], "Code generated") && strings.Contains(lines[i], "DO NOT EDIT") {
						goto next
					}
					if strings.Contains(lines[i], "DO NOT EDIT") {
						// original checks for generated header containing both? We'll check both conditions as above
					}
				}
			}
		}
		fails, err := lintFile(fp, cfg, enabledRules)
		if err != nil {
			all = append(all, Failure{
				Severity:       "warning",
				FailureMessage: fmt.Sprintf("invalid file %s: %s", fp, err.Error()),
				RuleName:       "",
				Category:       "validity",
				Confidence:     1,
				Position: Position{
					Start: Pos{Filename: fp, Line: 1, Column: 1, Offset: 0},
				},
			})
			continue
		}
		all = append(all, fails...)
	next:
	}
	return all, nil
}

func lintFile(filePath string, cfg *Config, enabledRules map[string]RuleConfig) ([]Failure, error) {
	fset := token.NewFileSet()
	src, err := os.ReadFile(filePath)
	if err != nil {
		return nil, err
	}
	file, err := parser.ParseFile(fset, filePath, src, parser.ParseComments)
	if err != nil {
		return nil, err
	}

	type dirEvent struct {
		line   int
		action string
		rules  []string
	}
	var events []dirEvent
	disabledAllPerLine := make(map[int]bool)
	disabledRulesPerLine := make(map[int]map[string]bool)

	for _, cg := range file.Comments {
		for _, c := range cg.List {
			text := c.Text
			if !strings.Contains(text, "revive:") {
				continue
			}
			trimmed := strings.TrimSpace(text)
			if strings.HasPrefix(trimmed, "//") {
				trimmed = strings.TrimPrefix(trimmed, "//")
				trimmed = strings.TrimSpace(trimmed)
			} else if strings.HasPrefix(trimmed, "/*") {
				trimmed = strings.TrimPrefix(trimmed, "/*")
				trimmed = strings.TrimSuffix(trimmed, "*/")
				trimmed = strings.TrimSpace(trimmed)
			}
			if !strings.HasPrefix(trimmed, "revive:") {
				continue
			}
			directivePart := strings.TrimPrefix(trimmed, "revive:")
			var action, rulePart string
			if strings.Contains(directivePart, ":") {
				parts := strings.SplitN(directivePart, ":", 2)
				action = parts[0]
				rulePart = parts[1]
			} else {
				action = directivePart
			}
			rulesList := []string{}
			if rulePart != "" {
				for _, r := range strings.Split(rulePart, ",") {
					r = strings.TrimSpace(r)
					if r != "" {
						rulesList = append(rulesList, r)
					}
				}
			}
			pos := fset.Position(c.Pos())
			switch action {
			case "disable-next-line":
				target := pos.Line + 1
				if len(rulesList) == 0 {
					disabledAllPerLine[target] = true
				} else {
					if disabledRulesPerLine[target] == nil {
						disabledRulesPerLine[target] = make(map[string]bool)
					}
					for _, rr := range rulesList {
						disabledRulesPerLine[target][rr] = true
					}
				}
			case "disable-line":
				target := pos.Line
				if len(rulesList) == 0 {
					disabledAllPerLine[target] = true
				} else {
					if disabledRulesPerLine[target] == nil {
						disabledRulesPerLine[target] = make(map[string]bool)
					}
					for _, rr := range rulesList {
						disabledRulesPerLine[target][rr] = true
					}
				}
			case "disable", "enable":
				events = append(events, dirEvent{line: pos.Line, action: action, rules: rulesList})
			}
		}
	}
	sort.Slice(events, func(i, j int) bool { return events[i].line < events[j].line })

	isDisabled := func(line int, rule string) bool {
		if disabledAllPerLine[line] {
			return true
		}
		if m, ok := disabledRulesPerLine[line]; ok {
			if m[rule] {
				return true
			}
		}
		return false
	}
	checkGlobal := func(line int, rule string) bool {
		disabledAll := false
		disabled := make(map[string]bool)
		for _, ev := range events {
			if ev.line > line {
				break
			}
			if ev.action == "disable" {
				if len(ev.rules) == 0 {
					disabledAll = true
				} else {
					for _, r := range ev.rules {
						disabled[r] = true
					}
				}
			} else if ev.action == "enable" {
				if len(ev.rules) == 0 {
					disabledAll = false
					disabled = make(map[string]bool)
				} else {
					for _, r := range ev.rules {
						delete(disabled, r)
					}
				}
			}
		}
		if disabledAll {
			return true
		}
		if disabled[rule] {
			return true
		}
		return false
	}

	var failures []Failure

	getSeverity := func(rule string) string {
		if rc, ok := enabledRules[rule]; ok && rc.Severity != "" {
			return rc.Severity
		}
		if cfg.Severity != "" {
			return cfg.Severity
		}
		return "warning"
	}
	getConfidence := func(rule string, def float64) float64 {
		if rc, ok := enabledRules[rule]; ok && rc.Confidence != nil {
			return *rc.Confidence
		}
		return def
	}

	if _, ok := enabledRules["var-declaration"]; ok {
		ast.Inspect(file, func(n ast.Node) bool {
			gen, ok := n.(*ast.GenDecl)
			if !ok {
				return true
			}
			if gen.Tok != token.VAR {
				return true
			}
			for _, spec := range gen.Specs {
				vs, ok := spec.(*ast.ValueSpec)
				if !ok {
					continue
				}
				if vs.Type == nil || len(vs.Values) == 0 {
					continue
				}
				for i, name := range vs.Names {
					pos := fset.Position(vs.Type.Pos())
					line := pos.Line
					if isDisabled(line, "var-declaration") || checkGlobal(line, "var-declaration") {
						continue
					}
					namePos := fset.Position(name.Pos())
					if isDisabled(namePos.Line, "var-declaration") || checkGlobal(namePos.Line, "var-declaration") {
						continue
					}
					start := fset.Position(vs.Type.Pos())
					end := fset.Position(vs.Type.End())
					typeStr := string(src[start.Offset:end.Offset])
					msg := fmt.Sprintf("should omit type %s from declaration of var %s; it will be inferred from the right-hand side", typeStr, name.Name)
					fail := Failure{
						Severity:       getSeverity("var-declaration"),
						FailureMessage: msg,
						RuleName:       "var-declaration",
						Category:       "type-inference",
						Confidence:     getConfidence("var-declaration", 0.8),
						Position: Position{
							Start: Pos{Filename: filePath, Offset: start.Offset, Line: start.Line, Column: start.Column},
							End:   Pos{Filename: filePath, Offset: end.Offset, Line: end.Line, Column: end.Column},
						},
					}
					_ = i
					failures = append(failures, fail)
				}
			}
			return true
		})
	}

	if _, ok := enabledRules["package-comments"]; ok {
		hasComment := false
		if file.Doc != nil && len(file.Doc.List) > 0 {
			hasComment = true
		}
		if !hasComment {
			line := 1
			if !isDisabled(line, "package-comments") && !checkGlobal(line, "package-comments") {
				pkgPos := fset.Position(file.Package)
				startOffset := pkgPos.Offset
				endOffset := fset.Position(file.Name.End()).Offset
				fail := Failure{
					Severity:       getSeverity("package-comments"),
					FailureMessage: "should have a package comment",
					RuleName:       "package-comments",
					Category:       "comments",
					Confidence:     getConfidence("package-comments", 1),
					Position: Position{
						Start: Pos{Filename: filePath, Offset: startOffset, Line: 1, Column: 1},
						End:   Pos{Filename: filePath, Offset: endOffset, Line: 1, Column: 1 + (endOffset - startOffset)},
					},
				}
				failures = append(failures, fail)
			}
		}
	}

	if _, ok := enabledRules["exported"]; ok {
		for _, decl := range file.Decls {
			if gen, ok := decl.(*ast.GenDecl); ok {
				if gen.Tok == token.TYPE {
					for _, spec := range gen.Specs {
						ts, ok := spec.(*ast.TypeSpec)
						if !ok || !ts.Name.IsExported() {
							continue
						}
						hasDoc := (ts.Doc != nil && len(ts.Doc.List) > 0) || (gen.Doc != nil && len(gen.Doc.List) > 0)
						if hasDoc {
							continue
						}
						pos := fset.Position(ts.Pos())
						if isDisabled(pos.Line, "exported") || checkGlobal(pos.Line, "exported") {
							continue
						}
						start := fset.Position(ts.Pos())
						end := fset.Position(ts.End())
						fail := Failure{
							Severity:       getSeverity("exported"),
							FailureMessage: fmt.Sprintf("exported type %s should have comment or be unexported", ts.Name.Name),
							RuleName:       "exported",
							Category:       "comments",
							Confidence:     getConfidence("exported", 1),
							Position: Position{
								Start: Pos{Filename: filePath, Offset: start.Offset, Line: start.Line, Column: start.Column},
								End:   Pos{Filename: filePath, Offset: end.Offset, Line: end.Line, Column: end.Column},
							},
						}
						failures = append(failures, fail)
					}
				}
			}
			if fn, ok := decl.(*ast.FuncDecl); ok {
				if fn.Name == nil || !fn.Name.IsExported() {
					continue
				}
				if fn.Doc != nil && len(fn.Doc.List) > 0 {
					continue
				}
				pos := fset.Position(fn.Pos())
				if isDisabled(pos.Line, "exported") || checkGlobal(pos.Line, "exported") {
					continue
				}
				start := fset.Position(fn.Pos())
				end := fset.Position(fn.End())
				kind := "function"
				if fn.Recv != nil {
					kind = "method"
				}
				fail := Failure{
					Severity:       getSeverity("exported"),
					FailureMessage: fmt.Sprintf("exported %s %s should have comment or be unexported", kind, fn.Name.Name),
					RuleName:       "exported",
					Category:       "comments",
					Confidence:     getConfidence("exported", 1),
					Position: Position{
						Start: Pos{Filename: filePath, Offset: start.Offset, Line: start.Line, Column: start.Column},
						End:   Pos{Filename: filePath, Offset: end.Offset, Line: end.Line, Column: end.Column},
					},
				}
				failures = append(failures, fail)
			}
		}
	}

	if _, ok := enabledRules["dot-imports"]; ok {
		for _, imp := range file.Imports {
			if imp.Name != nil && imp.Name.Name == "." {
				pos := fset.Position(imp.Pos())
				if isDisabled(pos.Line, "dot-imports") || checkGlobal(pos.Line, "dot-imports") {
					continue
				}
				start := fset.Position(imp.Pos())
				end := fset.Position(imp.End())
				fail := Failure{
					Severity:       getSeverity("dot-imports"),
					FailureMessage: "should not use dot imports",
					RuleName:       "dot-imports",
					Category:       "imports",
					Confidence:     getConfidence("dot-imports", 1),
					Position: Position{
						Start: Pos{Filename: filePath, Offset: start.Offset, Line: start.Line, Column: start.Column},
						End:   Pos{Filename: filePath, Offset: end.Offset, Line: end.Line, Column: end.Column},
					},
				}
				failures = append(failures, fail)
			}
		}
	}

	if _, ok := enabledRules["unused-parameter"]; ok {
		for _, decl := range file.Decls {
			fn, ok := decl.(*ast.FuncDecl)
			if !ok || fn.Type.Params == nil || fn.Body == nil {
				continue
			}
			used := make(map[string]bool)
			ast.Inspect(fn.Body, func(n ast.Node) bool {
				if ident, ok := n.(*ast.Ident); ok {
					used[ident.Name] = true
				}
				return true
			})
			for _, field := range fn.Type.Params.List {
				for _, name := range field.Names {
					if name.Name == "_" {
						continue
					}
					if used[name.Name] {
						continue
					}
					pos := fset.Position(name.Pos())
					if isDisabled(pos.Line, "unused-parameter") || checkGlobal(pos.Line, "unused-parameter") {
						continue
					}
					start := fset.Position(name.Pos())
					end := fset.Position(name.End())
					fail := Failure{
						Severity:       getSeverity("unused-parameter"),
						FailureMessage: fmt.Sprintf("parameter '%s' seems to be unused, consider removing or renaming it as _", name.Name),
						RuleName:       "unused-parameter",
						Category:       "bad practice",
						Confidence:     getConfidence("unused-parameter", 1),
						Position: Position{
							Start: Pos{Filename: filePath, Offset: start.Offset, Line: start.Line, Column: start.Column},
							End:   Pos{Filename: filePath, Offset: end.Offset, Line: end.Line, Column: end.Column},
						},
					}
					failures = append(failures, fail)
				}
			}
		}
	}

	if _, ok := enabledRules["receiver-naming"]; ok {
		receiverNames := make(map[string]string)
		for _, decl := range file.Decls {
			fn, ok := decl.(*ast.FuncDecl)
			if !ok || fn.Recv == nil || len(fn.Recv.List) == 0 {
				continue
			}
			recvField := fn.Recv.List[0]
			if len(recvField.Names) == 0 {
				continue
			}
			recvName := recvField.Names[0].Name
			var typeName string
			switch t := recvField.Type.(type) {
			case *ast.StarExpr:
				if ident, ok := t.X.(*ast.Ident); ok {
					typeName = ident.Name
				}
			case *ast.Ident:
				typeName = t.Name
			}
			if typeName == "" {
				continue
			}
			if prev, ok := receiverNames[typeName]; ok && prev != recvName {
				pos := fset.Position(fn.Pos())
				if isDisabled(pos.Line, "receiver-naming") || checkGlobal(pos.Line, "receiver-naming") {
					continue
				}
				start := fset.Position(fn.Pos())
				end := fset.Position(fn.End())
				fail := Failure{
					Severity:       getSeverity("receiver-naming"),
					FailureMessage: fmt.Sprintf("receiver name %s should be consistent with previous receiver name %s for %s", recvName, prev, typeName),
					RuleName:       "receiver-naming",
					Category:       "naming",
					Confidence:     getConfidence("receiver-naming", 1),
					Position: Position{
						Start: Pos{Filename: filePath, Offset: start.Offset, Line: start.Line, Column: start.Column},
						End:   Pos{Filename: filePath, Offset: end.Offset, Line: end.Line, Column: end.Column},
					},
				}
				failures = append(failures, fail)
			} else {
				receiverNames[typeName] = recvName
			}
		}
	}

	if _, ok := enabledRules["empty-block"]; ok {
		ast.Inspect(file, func(n ast.Node) bool {
			block, ok := n.(*ast.BlockStmt)
			if !ok {
				return true
			}
			if len(block.List) == 0 {
				pos := fset.Position(block.Pos())
				if isDisabled(pos.Line, "empty-block") || checkGlobal(pos.Line, "empty-block") {
					return true
				}
				start := fset.Position(block.Pos())
				end := fset.Position(block.End())
				fail := Failure{
					Severity:       getSeverity("empty-block"),
					FailureMessage: "this block is empty, you can remove it",
					RuleName:       "empty-block",
					Category:       "style",
					Confidence:     getConfidence("empty-block", 1),
					Position: Position{
						Start: Pos{Filename: filePath, Offset: start.Offset, Line: start.Line, Column: start.Column},
						End:   Pos{Filename: filePath, Offset: end.Offset, Line: end.Line, Column: end.Column},
					},
				}
				failures = append(failures, fail)
			}
			return true
		})
	}

	if _, ok := enabledRules["unreachable-code"]; ok {
		ast.Inspect(file, func(n ast.Node) bool {
			block, ok := n.(*ast.BlockStmt)
			if !ok {
				return true
			}
			foundReturn := false
			for _, stmt := range block.List {
				if foundReturn {
					pos := fset.Position(stmt.Pos())
					if isDisabled(pos.Line, "unreachable-code") || checkGlobal(pos.Line, "unreachable-code") {
						continue
					}
					start := fset.Position(stmt.Pos())
					end := fset.Position(stmt.End())
					fail := Failure{
						Severity:       getSeverity("unreachable-code"),
						FailureMessage: "unreachable code after this statement",
						RuleName:       "unreachable-code",
						Category:       "style",
						Confidence:     getConfidence("unreachable-code", 1),
						Position: Position{
							Start: Pos{Filename: filePath, Offset: start.Offset, Line: start.Line, Column: start.Column},
							End:   Pos{Filename: filePath, Offset: end.Offset, Line: end.Line, Column: end.Column},
						},
					}
					failures = append(failures, fail)
					break
				}
				if _, ok := stmt.(*ast.ReturnStmt); ok {
					foundReturn = true
				}
			}
			return true
		})
	}

	if _, ok := enabledRules["indent-error-flow"]; ok {
		ast.Inspect(file, func(n ast.Node) bool {
			ifStmt, ok := n.(*ast.IfStmt)
			if !ok || ifStmt.Else == nil || ifStmt.Body == nil || len(ifStmt.Body.List) == 0 {
				return true
			}
			if _, ok := ifStmt.Body.List[len(ifStmt.Body.List)-1].(*ast.ReturnStmt); !ok {
				return true
			}
			pos := fset.Position(ifStmt.Pos())
			if isDisabled(pos.Line, "indent-error-flow") || checkGlobal(pos.Line, "indent-error-flow") {
				return true
			}
			start := fset.Position(ifStmt.Pos())
			end := fset.Position(ifStmt.End())
			fail := Failure{
				Severity:       getSeverity("indent-error-flow"),
				FailureMessage: "if block ends with a return statement, so drop this else and outdent its block",
				RuleName:       "indent-error-flow",
				Category:       "style",
				Confidence:     getConfidence("indent-error-flow", 1),
				Position: Position{
					Start: Pos{Filename: filePath, Offset: start.Offset, Line: start.Line, Column: start.Column},
					End:   Pos{Filename: filePath, Offset: end.Offset, Line: end.Line, Column: end.Column},
				},
			}
			failures = append(failures, fail)
			return true
		})
	}

	if rc, ok := enabledRules["line-length-limit"]; ok {
		limit := 80
		if len(rc.Arguments) > 0 {
			switch v := rc.Arguments[0].(type) {
			case int64:
				limit = int(v)
			case float64:
				limit = int(v)
			case int:
				limit = v
			}
		}
		lines := strings.Split(string(src), "\n")
		offset := 0
		for i, line := range lines {
			lineNum := i + 1
			if len(line) > limit {
				if isDisabled(lineNum, "line-length-limit") || checkGlobal(lineNum, "line-length-limit") {
					offset += len(line) + 1
					continue
				}
				fail := Failure{
					Severity:       getSeverity("line-length-limit"),
					FailureMessage: fmt.Sprintf("line is %d characters, out of limit %d", len(line), limit),
					RuleName:       "line-length-limit",
					Category:       "style",
					Confidence:     getConfidence("line-length-limit", 1),
					Position: Position{
						Start: Pos{Filename: filePath, Offset: offset, Line: lineNum, Column: 0},
						End:   Pos{Filename: filePath, Offset: offset, Line: lineNum, Column: len(line)},
					},
				}
				failures = append(failures, fail)
			}
			offset += len(line) + 1
		}
	}

	if _, ok := enabledRules["string-of-int"]; ok {
		ast.Inspect(file, func(n ast.Node) bool {
			call, ok := n.(*ast.CallExpr)
			if !ok {
				return true
			}
			fun, ok := call.Fun.(*ast.Ident)
			if !ok || fun.Name != "string" || len(call.Args) != 1 {
				return true
			}
			if lit, ok := call.Args[0].(*ast.BasicLit); ok && lit.Kind == token.INT {
				pos := fset.Position(call.Pos())
				if isDisabled(pos.Line, "string-of-int") || checkGlobal(pos.Line, "string-of-int") {
					return true
				}
				start := fset.Position(call.Pos())
				end := fset.Position(call.End())
				fail := Failure{
					Severity:       getSeverity("string-of-int"),
					FailureMessage: "dubious conversion of an integer into a string, use strconv.Itoa",
					RuleName:       "string-of-int",
					Category:       "",
					Confidence:     getConfidence("string-of-int", 1),
					Position: Position{
						Start: Pos{Filename: filePath, Offset: start.Offset, Line: start.Line, Column: start.Column},
						End:   Pos{Filename: filePath, Offset: end.Offset, Line: end.Line, Column: end.Column},
					},
				}
				failures = append(failures, fail)
			}
			return true
		})
	}

	// Filter final with global check again (already done for each rule, but re-apply for safety)
	var final []Failure
	for _, f := range failures {
		if !isDisabled(f.Position.Start.Line, f.RuleName) && !checkGlobal(f.Position.Start.Line, f.RuleName) {
			final = append(final, f)
		}
	}
	return final, nil
}

func formatFailures(formatter string, failures []Failure, cfg *Config, enabledRules map[string]RuleConfig) ([]byte, error) {
	switch formatter {
	case "default":
		var buf bytes.Buffer
		for _, f := range failures {
			buf.WriteString(fmt.Sprintf("%s:%d:%d: %s\n", f.Position.Start.Filename, f.Position.Start.Line, f.Position.Start.Column, f.FailureMessage))
		}
		return buf.Bytes(), nil
	case "plain":
		var buf bytes.Buffer
		for _, f := range failures {
			buf.WriteString(fmt.Sprintf("%s:%d:%d: %s https://revive.run/r#%s\n", f.Position.Start.Filename, f.Position.Start.Line, f.Position.Start.Column, f.FailureMessage, f.RuleName))
		}
		return buf.Bytes(), nil
	case "unix":
		var buf bytes.Buffer
		for _, f := range failures {
			buf.WriteString(fmt.Sprintf("%s:%d:%d: [%s] %s\n", f.Position.Start.Filename, f.Position.Start.Line, f.Position.Start.Column, f.RuleName, f.FailureMessage))
		}
		return buf.Bytes(), nil
	case "json":
		if len(failures) == 0 {
			return []byte("null"), nil
		}
		data, err := json.Marshal(failures)
		if err != nil {
			return nil, err
		}
		return data, nil
	case "ndjson":
		if len(failures) == 0 {
			return []byte(""), nil
		}
		var buf bytes.Buffer
		for _, f := range failures {
			b, _ := json.Marshal(f)
			buf.Write(b)
			buf.WriteString("\n")
		}
		return buf.Bytes(), nil
	case "friendly":
		if len(failures) == 0 {
			return []byte(""), nil
		}
		var buf bytes.Buffer
		errorCount := 0
		warningCount := 0
		ruleCounts := make(map[string]int)
		for _, f := range failures {
			if f.Severity == "error" {
				errorCount++
			} else {
				warningCount++
			}
			ruleCounts[f.RuleName]++
		}
		for _, f := range failures {
			buf.WriteString(fmt.Sprintf("  ⚠  https://revive.run/r#%s  %s\n", f.RuleName, f.FailureMessage))
			buf.WriteString(fmt.Sprintf("  %s:%d:%d\n", f.Position.Start.Filename, f.Position.Start.Line, f.Position.Start.Column))
			buf.WriteString("\n")
		}
		buf.WriteString(fmt.Sprintf("⚠ %d problems (%d errors, %d warnings)\n", len(failures), errorCount, warningCount))
		buf.WriteString("\n")
		buf.WriteString("Warnings:\n")
		type rc struct {
			name  string
			count int
		}
		var rcs []rc
		for n, c := range ruleCounts {
			rcs = append(rcs, rc{n, c})
		}
		sort.Slice(rcs, func(i, j int) bool {
			if rcs[i].count != rcs[j].count {
				return rcs[i].count > rcs[j].count
			}
			return rcs[i].name < rcs[j].name
		})
		for _, r := range rcs {
			buf.WriteString(fmt.Sprintf("  %d  %s\n", r.count, r.name))
		}
		buf.WriteString("\n")
		return buf.Bytes(), nil
	case "stylish":
		if len(failures) == 0 {
			return []byte(""), nil
		}
		var buf bytes.Buffer
		groups := make(map[string][]Failure)
		var fileOrder []string
		seen := make(map[string]bool)
		for _, f := range failures {
			fn := f.Position.Start.Filename
			if !seen[fn] {
				seen[fn] = true
				fileOrder = append(fileOrder, fn)
			}
			groups[fn] = append(groups[fn], f)
		}
		sort.Strings(fileOrder)
		for _, fn := range fileOrder {
			buf.WriteString(fmt.Sprintf("%s\n", fn))
			fails := groups[fn]
			sort.Slice(fails, func(i, j int) bool {
				if fails[i].Position.Start.Line != fails[j].Position.Start.Line {
					return fails[i].Position.Start.Line < fails[j].Position.Start.Line
				}
				return fails[i].Position.Start.Column < fails[j].Position.Start.Column
			})
			for _, f := range fails {
				buf.WriteString(fmt.Sprintf("  (%d, %d)  https://revive.run/r#%s  %s\n", f.Position.Start.Line, f.Position.Start.Column, f.RuleName, f.FailureMessage))
			}
			buf.WriteString("\n")
		}
		errorCount := 0
		warningCount := 0
		for _, f := range failures {
			if f.Severity == "error" {
				errorCount++
			} else {
				warningCount++
			}
		}
		buf.WriteString("\n")
		buf.WriteString(fmt.Sprintf(" ✖ %d problems (%d errors) (%d warnings)\n", len(failures), errorCount, warningCount))
		return buf.Bytes(), nil
	case "checkstyle":
		type CheckstyleError struct {
			Line     int    `xml:"line,attr"`
			Column   int    `xml:"column,attr"`
			Message  string `xml:"message,attr"`
			Severity string `xml:"severity,attr"`
			Source   string `xml:"source,attr"`
		}
		type CheckstyleFile struct {
			Name   string            `xml:"name,attr"`
			Errors []CheckstyleError `xml:"error"`
		}
		type Checkstyle struct {
			XMLName xml.Name         `xml:"checkstyle"`
			Version string           `xml:"version,attr"`
			Files   []CheckstyleFile `xml:"file"`
		}
		groups := make(map[string][]Failure)
		var fileOrder []string
		seen := make(map[string]bool)
		for _, f := range failures {
			fn := f.Position.Start.Filename
			if !seen[fn] {
				seen[fn] = true
				fileOrder = append(fileOrder, fn)
			}
			groups[fn] = append(groups[fn], f)
		}
		sort.Strings(fileOrder)
		var cs Checkstyle
		cs.Version = "5.0"
		for _, fn := range fileOrder {
			var cf CheckstyleFile
			cf.Name = fn
			for _, f := range groups[fn] {
				msg := fmt.Sprintf("%s (confidence %g)", f.FailureMessage, f.Confidence)
				cf.Errors = append(cf.Errors, CheckstyleError{
					Line: f.Position.Start.Line, Column: f.Position.Start.Column,
					Message: msg, Severity: f.Severity, Source: "revive/" + f.RuleName,
				})
			}
			cs.Files = append(cs.Files, cf)
		}
		out, err := xml.MarshalIndent(cs, "", "    ")
		if err != nil {
			return nil, err
		}
		var buf bytes.Buffer
		buf.WriteString("<?xml version='1.0' encoding='UTF-8'?>\n")
		buf.Write(out)
		buf.WriteString("\n")
		return buf.Bytes(), nil
	case "sarif":
		type SarifLocation struct {
			PhysicalLocation struct {
				ArtifactLocation struct {
					Uri string `json:"uri"`
				} `json:"artifactLocation"`
				Region struct {
					StartColumn int `json:"startColumn"`
					StartLine   int `json:"startLine"`
				} `json:"region"`
			} `json:"physicalLocation"`
		}
		type SarifResult struct {
			Level     string          `json:"level,omitempty"`
			Locations []SarifLocation `json:"locations"`
			Message   struct {
				Text string `json:"text"`
			} `json:"message"`
			RuleId string `json:"ruleId"`
		}
		type SarifRule struct {
			HelpUri string `json:"helpUri"`
			Id      string `json:"id"`
			Properties struct {
				Severity string `json:"severity"`
			} `json:"properties"`
		}
		type SarifDriver struct {
			InformationUri string      `json:"informationUri"`
			Name           string      `json:"name"`
			Rules          []SarifRule `json:"rules,omitempty"`
		}
		type SarifTool struct {
			Driver SarifDriver `json:"driver"`
		}
		type SarifRun struct {
			Results []SarifResult `json:"results,omitempty"`
			Tool    SarifTool     `json:"tool"`
		}
		type Sarif struct {
			Runs    []SarifRun `json:"runs"`
			Version string     `json:"version"`
		}
		var sarif Sarif
		sarif.Version = "2.1.0"
		var run SarifRun
		run.Tool.Driver.InformationUri = "https://revive.run"
		run.Tool.Driver.Name = "revive"
		if len(failures) == 0 {
			// Provide at least one rule to match original empty behavior
			if len(enabledRules) == 0 {
				var r SarifRule
				r.HelpUri = "https://revive.run/r#var-declaration"
				r.Id = "var-declaration"
				r.Properties.Severity = ""
				run.Tool.Driver.Rules = append(run.Tool.Driver.Rules, r)
			} else {
				// Use first enabled rule sorted
				var names []string
				for n := range enabledRules {
					names = append(names, n)
				}
				sort.Strings(names)
				if len(names) > 0 {
					var r SarifRule
					r.HelpUri = "https://revive.run/r#" + names[0]
					r.Id = names[0]
					r.Properties.Severity = ""
					run.Tool.Driver.Rules = append(run.Tool.Driver.Rules, r)
				}
			}
		} else {
			for _, f := range failures {
				var res SarifResult
				res.Level = f.Severity
				res.RuleId = f.RuleName
				res.Message.Text = f.FailureMessage
				var loc SarifLocation
				loc.PhysicalLocation.ArtifactLocation.Uri = f.Position.Start.Filename
				loc.PhysicalLocation.Region.StartColumn = f.Position.Start.Column
				loc.PhysicalLocation.Region.StartLine = f.Position.Start.Line
				res.Locations = append(res.Locations, loc)
				run.Results = append(run.Results, res)
			}
			// Rules: use last failure's rule to match original's observed single-rule behavior
			last := failures[len(failures)-1]
			var r SarifRule
			r.HelpUri = "https://revive.run/r#" + last.RuleName
			r.Id = last.RuleName
			r.Properties.Severity = last.Severity
			run.Tool.Driver.Rules = append(run.Tool.Driver.Rules, r)
		}
		sarif.Runs = append(sarif.Runs, run)
		data, err := json.MarshalIndent(sarif, "", "  ")
		if err != nil {
			return nil, err
		}
		return data, nil
	default:
		return nil, fmt.Errorf("unknown formatter %s", formatter)
	}
}
