nl -ba main.go | sed -n '1006,1080p'
# The file shows correct: one exported block with extra closing braces at 1072-1075
# Let's see what is at 1072-1075: 2 closing braces extra, then dot-imports
# Count braces: exported block opened at 1006 with "if _, ok :=...", then "if file.Name.Name != "main" {" at 1007, then "for _, decl :=..." at 1008, then inner for, etc. At end we have 1072 "}", 1073 blank, 1074 "}", 1075 "}". That's two extra closing? Let's count: 
# - for loop at 1008 needs closing at 1071? Actually for loop ends at 1071, then if file.Name != main closes at 1072, then outer if closes at 1073? But we have 3 closing braces: 1072, 1074, 1075. Actually 1072 closes for loop? Let's count: 
# The for loop started at 1008, it should close at maybe 1071 (we see 1071 is " }"? Actually 1071 is "\t\t}" which closes for loop? Then 1072 "\t}" closes if file.Name != main, then 1073 "}" closes outer if, then 1074 "}" is extra? Let's check.
# We had earlier: at 1071 " }", 1072 blank, 1073 "}", 1074 blank, 1075 "}". That's 3 closing braces after for loop end at 1070? Let's recount from 1041
# At 1041 "if fn, ok := decl.(*ast.FuncDecl)" started, its closing is at 1070? Actually 1041 is inside for loop, but we have if gen at 1009, for spec at 1010, etc.
# The structure is messy.

# Simpler: Let's rewrite the exported block completely.

cat > /tmp/exported_fix.go <<'EOF'
	if _, ok := enabledRules["exported"]; ok {
		if file.Name.Name != "main" {
			for _, decl := range file.Decls {
				if gen, ok := decl.(*ast.GenDecl); ok {
					if gen.Tok == token.TYPE {
						for _, spec := range gen.Specs {
							ts, ok := spec.(*ast.TypeSpec)
							if !ok || !ts.Name.IsExported() {
								continue
							}
							hasDoc := (ts.Doc != nil && len(ts.Doc.List) > 0) || (gen.Doc != nil && len(gen.Doc.List) > 0)
							if hasDoc {
								continue
							}
							pos := fset.Position(ts.Pos())
							if isDisabled(pos.Line, "exported") || checkGlobal(pos.Line, "exported") {
								continue
							}
							start := fset.Position(ts.Pos())
							end := fset.Position(ts.End())
							fail := Failure{
								Severity:       getSeverity("exported"),
								FailureMessage: fmt.Sprintf("exported type %s should have comment or be unexported", ts.Name.Name),
								RuleName:       "exported",
								Category:       "comments",
								Confidence:     getConfidence("exported", 1),
								Position: Position{
									Start: Pos{Filename: filePath, Offset: start.Offset, Line: start.Line, Column: start.Column},
									End:   Pos{Filename: filePath, Offset: end.Offset, Line: end.Line, Column: end.Column},
								},
							}
							failures = append(failures, fail)
						}
					}
				}
				if fn, ok := decl.(*ast.FuncDecl); ok {
					if fn.Name == nil || !fn.Name.IsExported() {
						continue
					}
					if fn.Doc != nil && len(fn.Doc.List) > 0 {
						continue
					}
					pos := fset.Position(fn.Pos())
					if isDisabled(pos.Line, "exported") || checkGlobal(pos.Line, "exported") {
						continue
					}
					start := fset.Position(fn.Pos())
					end := fset.Position(fn.End())
					kind := "function"
					if fn.Recv != nil {
						kind = "method"
					}
					fail := Failure{
						Severity:       getSeverity("exported"),
						FailureMessage: fmt.Sprintf("exported %s %s should have comment or be unexported", kind, fn.Name.Name),
						RuleName:       "exported",
						Category:       "comments",
						Confidence:     getConfidence("exported", 1),
						Position: Position{
							Start: Pos{Filename: filePath, Offset: start.Offset, Line: start.Line, Column: start.Column},
							End:   Pos{Filename: filePath, Offset: end.Offset, Line: end.Line, Column: end.Column},
						},
					}
					failures = append(failures, fail)
				}
			}
		}
	}
EOF

python3 - <<'PY'
import re
path="/workspace/main.go"
content=open(path).read()
# Find exported block from "if _, ok := enabledRules[\"exported\"]" to "if _, ok := enabledRules[\"dot-imports\"]"
pattern = r'if _, ok := enabledRules\["exported"\]; ok \{.*?if _, ok := enabledRules\["dot-imports"\]; ok \{'
m=re.search(pattern, content, re.DOTALL)
if m:
    print("found")
    new_block = open("/tmp/exported_fix.go").read() + "\n\tif _, ok := enabledRules[\"dot-imports\"]; ok {"
    content = content[:m.start()] + new_block + content[m.end():]
    open(path,"w").write(content)
    print("replaced")
else:
    print("not found")
PY
