{"command":"cd /workspace
# Fix checkstyle to use self-closing tag and handle offset for line-length-limit

python3 - <<'PY'
path="/workspace/main.go"
content=open(path).read()

# Fix checkstyle: need to handle xml marshaling to produce self-closing tags.
# Our current implementation uses xml.MarshalIndent which produces <error></error> not self-closing.
# We need to manually generate checkstyle XML to match original format.

old_checkstyle = """	case "checkstyle":
		type CheckstyleError struct {
			Line     int    `xml:"line,attr"`
			Column   int    `xml:"column,attr"`
			Message  string `xml:"message,attr"`
			Severity string `xml:"severity,attr"`
			Source   string `xml:"source,attr"`
		}
		type CheckstyleFile struct {
			Name   string            `xml:"name,attr"`
			Errors []CheckstyleError `xml:"error"`
		}
		type Checkstyle struct {
			XMLName xml.Name         `xml:"checkstyle"`
			Version string           `xml:"version,attr"`
			Files   []CheckstyleFile `xml:"file"`
		}
		groups := make(map[string][]Failure)
		var fileOrder []string
		seen := make(map[string]bool)
		for _, f := range failures {
			fn := f.Position.Start.Filename
			if !seen[fn] {
				seen[fn] = true
				fileOrder = append(fileOrder, fn)
			}
			groups[fn] = append(groups[fn], f)
		}
		sort.Strings(fileOrder)
		var cs Checkstyle
		cs.Version = "5.0"
		for _, fn := range fileOrder {
			var cf CheckstyleFile
			cf.Name = fn
			for _, f := range groups[fn] {
				msg := fmt.Sprintf("%s (confidence %g)", f.FailureMessage, f.Confidence)
				cf.Errors = append(cf.Errors, CheckstyleError{
					Line: f.Position.Start.Line, Column: f.Position.Start.Column,
					Message: msg, Severity: f.Severity, Source: "revive/" + f.RuleName,
				})
			}
			cs.Files = append(cs.Files, cf)
		}
		out, err := xml.MarshalIndent(cs, "", "    ")
		if err != nil {
			return nil, err
		}
		var buf bytes.Buffer
		buf.WriteString("<?xml version='1.0' encoding='UTF-8'?>\\n")
		buf.Write(out)
		buf.WriteString("\\n")
		return buf.Bytes(), nil"""

new_checkstyle = """	case "checkstyle":
		// Manual XML generation to match original format self-closing tags
		groups := make(map[string][]Failure)
		var fileOrder []string
		seen := make(map[string]bool)
		for _, f := range failures {
			fn := f.Position.Start.Filename
			if !seen[fn] {
				seen[fn] = true
				fileOrder = append(fileOrder, fn)
			}
			groups[fn] = append(groups[fn], f)
		}
		sort.Strings(fileOrder)
		var buf bytes.Buffer
		buf.WriteString("<?xml version='1.0' encoding='UTF-8'?>\\n")
		buf.WriteString("<checkstyle version=\\"5.0\\">\\n")
		for _, fn := range fileOrder {
			buf.WriteString(fmt.Sprintf("    <file name=\\"%s\\">\\n", fn))
			for _, f := range groups[fn] {
				msg := fmt.Sprintf("%s (confidence %g)", f.FailureMessage, f.Confidence)
				// Escape XML special chars in message
				msg = strings.ReplaceAll(msg, "&", "&amp;")
				msg = strings.ReplaceAll(msg, "<", "&lt;")
				msg = strings.ReplaceAll(msg, ">", "&gt;")
				msg = strings.ReplaceAll(msg, "\\"", "&quot;")
				msg = strings.ReplaceAll(msg, "'", "&apos;")
				buf.WriteString(fmt.Sprintf("      <error line=\\"%d\\" column=\\"%d\\" message=\\"%s\\" severity=\\"%s\\" source=\\"revive/%s\\"/>\\n", f.Position.Start.Line, f.Position.Start.Column, msg, f.Severity, f.RuleName))
			}
			buf.WriteString("    </file>\\n")
		}
		buf.WriteString("</checkstyle>\\n")
		return buf.Bytes(), nil"""

if old_checkstyle in content:
    content=content.replace(old_checkstyle, new_checkstyle)
    print("fixed checkstyle")
else:
    print("checkstyle not found exact")
    # Try to find via regex
    import re
    m=re.search(r'case "checkstyle":.*?return buf\.Bytes\(\), nil', content, re.DOTALL)
    if m:
        print(m.group(0)[:500])
    else:
        print("no match")

open(path,"w").write(content)
PY

# Also need to fix line-length-limit offset: original offset 0
python3 - <<'PY'
path="/workspace/main.go"
content=open(path).read()
# Find line-length-limit handling
old_ll = """		lines := strings.Split(string(src), "\\n")
		offset := 0
		for i, line := range lines {
			lineNum := i + 1
			if len(line) > limit {
				if isDisabled(lineNum, "line-length-limit") || checkGlobal(lineNum, "line-length-limit") {
					offset += len(line) + 1
					continue
				}
				fail := Failure{
					Severity:       getSeverity("line-length-limit"),
					FailureMessage: fmt.Sprintf("line is %d characters, out of limit %d", len(line), limit),
					RuleName:       "line-length-limit",
					Category:       "style",
					Confidence:     getConfidence("line-length-limit", 1),
					Position: Position{
						Start: Pos{Filename: filePath, Offset: offset, Line: lineNum, Column: 0},
						End:   Pos{Filename: filePath, Offset: offset, Line: lineNum, Column: len(line)},
					},
				}
				failures = append(failures, fail)
			}
			offset += len(line) + 1
		}"""

new_ll = """		lines := strings.Split(string(src), "\\n")
		for i, line := range lines {
			lineNum := i + 1
			if len(line) > limit {
				if isDisabled(lineNum, "line-length-limit") || checkGlobal(lineNum, "line-length-limit") {
					continue
				}
				fail := Failure{
					Severity:       getSeverity("line-length-limit"),
					FailureMessage: fmt.Sprintf("line is %d characters, out of limit %d", len(line), limit),
					RuleName:       "line-length-limit",
					Category:       "style",
					Confidence:     getConfidence("line-length-limit", 1),
					Position: Position{
						Start: Pos{Filename: filePath, Offset: 0, Line: lineNum, Column: 0},
						End:   Pos{Filename: filePath, Offset: 0, Line: lineNum, Column: len(line)},
					},
				}
				failures = append(failures, fail)
			}
		}"""

if old_ll in content:
    content=content.replace(old_ll, new_ll)
    print("fixed line-length")
else:
    print("line-length not found")
    import re
    m=re.search(r'lines := strings\.Split\(string\(src\), "\\n"\)\s+offset := 0.*?offset \+= len\(line\) \+ 1\n\t\t\}', content, re.DOTALL)
    if m:
        print(m.group(0)[:500])

open(path,"w").write(content)
PY
"}

